--
-- Name: advance_agent_operational_read_revision(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.advance_agent_operational_read_revision(p_company_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'private', 'pg_temp'
    AS $$
begin
  if p_company_id is null then
    return;
  end if;
  insert into private.agent_operational_read_revisions as revision (
    company_id,
    source_revision,
    updated_at
  ) values (
    p_company_id,
    1,
    statement_timestamp()
  )
  on conflict (company_id) do update
  set source_revision = revision.source_revision + 1,
      updated_at = excluded.updated_at
  where revision.source_revision < 9007199254740991;
  if not found then
    raise exception 'agent_operational_read_revision_exhausted'
      using errcode = '22003';
  end if;
end;
$$;


ALTER FUNCTION private.advance_agent_operational_read_revision(p_company_id uuid) OWNER TO postgres;

--
-- Name: advance_agent_read_domain_revisions(uuid[], text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.advance_agent_read_domain_revisions(p_company_ids uuid[], p_domain text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'private', 'pg_temp'
    AS $$
declare
  v_expected_count integer;
  v_advanced_count integer;
begin
  if p_domain is null or not exists (
    select 1
    from private.agent_read_domains domain
    where domain.domain = p_domain
  ) then
    raise exception 'agent_read_domain_revision_invalid_domain'
      using errcode = '22023';
  end if;

  select count(*)::integer
    into v_expected_count
  from (
    select distinct company_id
    from unnest(coalesce(p_company_ids, array[]::uuid[])) company_id
    where company_id is not null
  ) distinct_companies;

  if v_expected_count = 0 then
    return;
  end if;

  -- One ordered statement gives cross-tenant moves a consistent lock order.
  insert into private.agent_read_domain_revisions as revision (
    company_id,
    domain,
    source_revision,
    updated_at
  )
  select
    distinct_companies.company_id,
    p_domain,
    1,
    statement_timestamp()
  from (
    select distinct company_id
    from unnest(p_company_ids) company_id
    where company_id is not null
    order by company_id
  ) distinct_companies
  on conflict (company_id, domain) do update
  set source_revision = revision.source_revision + 1,
      updated_at = excluded.updated_at
  where revision.source_revision < 9007199254740991;

  get diagnostics v_advanced_count = row_count;
  if v_advanced_count is distinct from v_expected_count then
    raise exception 'agent_read_domain_revision_exhausted'
      using errcode = '22003';
  end if;
end;
$$;


ALTER FUNCTION private.advance_agent_read_domain_revisions(p_company_ids uuid[], p_domain text) OWNER TO postgres;

--
-- Name: agent_discovery_opportunity_source_is_invalid(uuid, uuid, uuid, uuid, text, text, text, timestamp with time zone, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.agent_discovery_opportunity_source_is_invalid(p_client_ref uuid, p_client_id uuid, p_project_ref uuid, p_project_id uuid, p_title text, p_address text, p_stage text, p_created_at timestamp with time zone, p_updated_at timestamp with time zone, p_archived_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'private', 'pg_temp'
    AS $$
  select coalesce(
    p_client_ref is not null
      and p_client_id is not null
      and p_client_ref is distinct from p_client_id
    or p_project_ref is not null
      and p_project_id is not null
      and p_project_ref is distinct from p_project_id
    or p_title is null
    or nullif(private.agent_trim_discovery_display_text(p_title), '') is null
    or octet_length(
      private.agent_trim_discovery_display_text(p_title)
    ) > 1000
    or private.agent_normalize_discovery_text(p_title) is null
    or p_address is not null and (
      nullif(
        private.agent_trim_discovery_display_text(p_address), ''
      ) is null
      or octet_length(
        private.agent_trim_discovery_display_text(p_address)
      ) > 2000
      or private.agent_normalize_discovery_text(p_address) is null
    )
    or p_stage is null
    or p_stage not in (
      'new_lead', 'qualifying', 'quoting', 'quoted', 'follow_up',
      'negotiation', 'won', 'lost', 'discarded'
    )
    or p_created_at is null
    or p_updated_at is null
    or not isfinite(p_created_at)
    or not isfinite(p_updated_at)
    or extract(year from p_created_at at time zone 'UTC')
      not between 1 and 9999
    or extract(year from p_updated_at at time zone 'UTC')
      not between 1 and 9999
    or p_archived_at is not null and not isfinite(p_archived_at)
    or p_created_at > p_updated_at,
    true
  );
$$;


ALTER FUNCTION private.agent_discovery_opportunity_source_is_invalid(p_client_ref uuid, p_client_id uuid, p_project_ref uuid, p_project_id uuid, p_title text, p_address text, p_stage text, p_created_at timestamp with time zone, p_updated_at timestamp with time zone, p_archived_at timestamp with time zone) OWNER TO postgres;

--
-- Name: agent_discovery_project_source_is_invalid(text, uuid, text, text, text, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.agent_discovery_project_source_is_invalid(p_opportunity_id text, p_opportunity_ref uuid, p_title text, p_address text, p_status text, p_created_at timestamp with time zone, p_updated_at timestamp with time zone, p_start_date timestamp with time zone, p_end_date timestamp with time zone) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'private', 'pg_temp'
    AS $$
  select coalesce(
    p_opportunity_id is not null
      and private.agent_uuid_from_legacy_text(p_opportunity_id) is null
    or p_opportunity_ref is not null
      and p_opportunity_id is not null
      and p_opportunity_ref is distinct from
        private.agent_uuid_from_legacy_text(p_opportunity_id)
    or p_title is null
    or nullif(private.agent_trim_discovery_display_text(p_title), '') is null
    or octet_length(
      private.agent_trim_discovery_display_text(p_title)
    ) > 1000
    or private.agent_normalize_discovery_text(p_title) is null
    or p_address is not null and (
      nullif(
        private.agent_trim_discovery_display_text(p_address), ''
      ) is null
      or octet_length(
        private.agent_trim_discovery_display_text(p_address)
      ) > 2000
      or private.agent_normalize_discovery_text(p_address) is null
    )
    or p_status is null
    or p_status not in (
      'rfq', 'estimated', 'accepted', 'in_progress', 'completed',
      'closed', 'archived'
    )
    or p_created_at is null
    or p_updated_at is null
    or not isfinite(p_created_at)
    or not isfinite(p_updated_at)
    or extract(year from p_created_at at time zone 'UTC')
      not between 1 and 9999
    or extract(year from p_updated_at at time zone 'UTC')
      not between 1 and 9999
    or p_created_at > p_updated_at
    or p_start_date is not null and (
      not isfinite(p_start_date)
      or extract(year from p_start_date at time zone 'UTC')
        not between 1 and 9999
    )
    or p_end_date is not null and (
      not isfinite(p_end_date)
      or extract(year from p_end_date at time zone 'UTC')
        not between 1 and 9999
    ),
    true
  );
$$;


ALTER FUNCTION private.agent_discovery_project_source_is_invalid(p_opportunity_id text, p_opportunity_ref uuid, p_title text, p_address text, p_status text, p_created_at timestamp with time zone, p_updated_at timestamp with time zone, p_start_date timestamp with time zone, p_end_date timestamp with time zone) OWNER TO postgres;

