--
-- Name: agent_normalize_discovery_email(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.agent_normalize_discovery_email(p_value text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'private', 'pg_temp'
    AS $_$
declare
  v_value text;
begin
  v_value := private.agent_normalize_discovery_text(p_value);
  if v_value is null
     or char_length(v_value) not between 3 and 200
     or v_value ~ '[[:space:]]'
     or position('@' in v_value) not between 2 and 65
     or octet_length(split_part(v_value, '@', 1)) > 64
     or v_value !~ '^[a-z0-9!#$%&''*+/=?^_`{|}~-]+(?:[.][a-z0-9!#$%&''*+/=?^_`{|}~-]+)*@[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:[.][a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+$' then
    return null;
  end if;
  return v_value;
end;
$_$;


ALTER FUNCTION private.agent_normalize_discovery_email(p_value text) OWNER TO postgres;

--
-- Name: agent_normalize_discovery_phone(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.agent_normalize_discovery_phone(p_value text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'private', 'pg_temp'
    AS $_$
declare
  v_value text;
  v_national text;
begin
  v_value := private.agent_normalize_discovery_text(p_value);
  if v_value is null or v_value !~ '^[+0-9(). -]+$' then
    return null;
  end if;
  v_value := regexp_replace(v_value, '[(). -]', '', 'g');
  if left(v_value, 2) = '+1' then
    v_national := substr(v_value, 3);
  elsif char_length(v_value) = 10 and left(v_value, 1) <> '+' then
    v_national := v_value;
  else
    return null;
  end if;
  if v_national !~ '^[2-9][0-9]{2}[2-9][0-9]{6}$' then
    return null;
  end if;
  return '+1' || v_national;
end;
$_$;


ALTER FUNCTION private.agent_normalize_discovery_phone(p_value text) OWNER TO postgres;

--
-- Name: agent_normalize_discovery_text(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.agent_normalize_discovery_text(p_value text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_value text;
begin
  if not private.agent_discovery_unicode15_text_is_supported(p_value)
     or octet_length(p_value) > 8192
     or p_value collate "und-x-icu" ~ '[[:cntrl:]]'
     or position(chr(1564) in p_value) > 0
     or position(chr(8206) in p_value) > 0
     or position(chr(8207) in p_value) > 0
     or position(chr(8234) in p_value) > 0
     or position(chr(8235) in p_value) > 0
     or position(chr(8236) in p_value) > 0
     or position(chr(8237) in p_value) > 0
     or position(chr(8238) in p_value) > 0
     or position(chr(8294) in p_value) > 0
     or position(chr(8295) in p_value) > 0
     or position(chr(8296) in p_value) > 0
     or position(chr(8297) in p_value) > 0
     or position(chr(65279) in p_value) > 0 then
    return null;
  end if;
  v_value := lower(private.agent_trim_discovery_display_text(
    regexp_replace(
      normalize(p_value, NFKC) collate "und-x-icu",
      '[[:space:]]+',
      ' ',
      'g'
    )
  ) collate "und-x-icu");
  if v_value = '' then
    return null;
  end if;
  return v_value;
end;
$$;


ALTER FUNCTION private.agent_normalize_discovery_text(p_value text) OWNER TO postgres;

--
-- Name: agent_p2_optional_canonical_text(text, integer, integer, boolean); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.agent_p2_optional_canonical_text(p_value text, p_maximum_scalars integer, p_maximum_utf8_bytes integer, p_allow_text_whitespace boolean) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO ''
    AS $$
declare
  v_value text;
begin
  if p_maximum_scalars < 1 or p_maximum_utf8_bytes < 1 then
    return null;
  end if;

  v_value := normalize(
    private.agent_trim_discovery_display_text(p_value),
    NFC
  );
  if v_value = ''
     or pg_catalog.char_length(v_value) > p_maximum_scalars
     or pg_catalog.octet_length(v_value) > p_maximum_utf8_bytes
     or not private.agent_discovery_unicode15_text_is_supported(v_value)
     or not private.agent_prompt_text_is_safe(
       v_value,
       p_allow_text_whitespace
     ) then
    return null;
  end if;
  return v_value;
end;
$$;


ALTER FUNCTION private.agent_p2_optional_canonical_text(p_value text, p_maximum_scalars integer, p_maximum_utf8_bytes integer, p_allow_text_whitespace boolean) OWNER TO postgres;

--
-- Name: agent_prompt_text_is_safe(text, boolean); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.agent_prompt_text_is_safe(p_value text, p_allow_text_whitespace boolean) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_character text;
  v_code integer;
begin
  for v_character in
    select regexp_split_to_table(p_value, '')
  loop
    v_code := ascii(v_character);
    if (
      (v_code between 0 and 31 and not (
        p_allow_text_whitespace and v_code in (9, 10)
      ))
      or v_code between 127 and 159
      or v_code in (173, 847, 1564, 6158, 8203, 8206, 8207, 8288, 65279)
      or v_code between 8234 and 8238
      or v_code between 8289 and 8303
      or v_code between 65529 and 65531
      or v_code between 917504 and 917631
    ) then
      return false;
    end if;
  end loop;
  return true;
end;
$$;


ALTER FUNCTION private.agent_prompt_text_is_safe(p_value text, p_allow_text_whitespace boolean) OWNER TO postgres;

--
-- Name: agent_read_domain_uuid_from_text(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.agent_read_domain_uuid_from_text(p_value text) RETURNS uuid
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
  select case
    when p_value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then lower(p_value)::uuid
  end;
$_$;


ALTER FUNCTION private.agent_read_domain_uuid_from_text(p_value text) OWNER TO postgres;

--
-- Name: agent_trim_discovery_display_text(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.agent_trim_discovery_display_text(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select btrim(
    p_value,
    chr(9) || chr(10) || chr(11) || chr(12) || chr(13) || chr(32) ||
    chr(160) || chr(5760) || chr(8192) || chr(8193) || chr(8194) ||
    chr(8195) || chr(8196) || chr(8197) || chr(8198) || chr(8199) ||
    chr(8200) || chr(8201) || chr(8202) || chr(8232) || chr(8233) ||
    chr(8239) || chr(8287) || chr(12288) || chr(65279)
  )
$$;


ALTER FUNCTION private.agent_trim_discovery_display_text(p_value text) OWNER TO postgres;

--
-- Name: agent_uuid_from_legacy_text(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.agent_uuid_from_legacy_text(p_value text) RETURNS uuid
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
  select case
    when p_value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then lower(p_value)::uuid
  end;
$_$;


ALTER FUNCTION private.agent_uuid_from_legacy_text(p_value text) OWNER TO postgres;

--
-- Name: assert_canonical_override_payload(jsonb, boolean); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.assert_canonical_override_payload(p_payload jsonb, p_require_registered boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
declare
  v_canonical jsonb;
begin
  if p_payload is null or jsonb_typeof(p_payload) <> 'array' then
    raise exception 'invalid_override_payload'
      using errcode = '22023';
  end if;

  if exists (
    select 1
      from jsonb_array_elements(p_payload) entry
     where jsonb_typeof(entry) <> 'object'
        or not (entry ?& array['permission', 'scope', 'granted'])
        or (select count(*) from jsonb_object_keys(entry)) <> 3
        or jsonb_typeof(entry -> 'permission') <> 'string'
        or nullif(entry ->> 'permission', '') is null
        or jsonb_typeof(entry -> 'scope') not in ('string', 'null')
        or jsonb_typeof(entry -> 'granted') <> 'boolean'
        or (
          p_require_registered
          and
          not (entry ->> 'granted')::boolean
          and jsonb_typeof(entry -> 'scope') <> 'null'
        )
  ) then
    raise exception 'invalid_override_payload'
      using errcode = '22023';
  end if;

  if exists (
    select 1
      from jsonb_array_elements(p_payload) entry
     group by entry ->> 'permission'
    having count(*) > 1
  ) then
    raise exception 'duplicate_permission'
      using errcode = '22023';
  end if;

  select coalesce(jsonb_agg(entry order by entry ->> 'permission'), '[]'::jsonb)
    into v_canonical
    from jsonb_array_elements(p_payload) entry;

  if p_payload is distinct from v_canonical then
    raise exception 'override_payload_not_canonical'
      using errcode = '22023';
  end if;

  if p_require_registered and exists (
    select 1
      from jsonb_array_elements(p_payload) entry
      left join private.lead_permission_editor_registry registry
        on registry.permission = entry ->> 'permission'
     where registry.permission is null
        or (
          jsonb_typeof(entry -> 'scope') = 'string'
          and not ((entry ->> 'scope') = any(registry.scopes))
        )
  ) then
    raise exception 'unsupported_scope_or_unregistered_permission'
      using errcode = '22023';
  end if;
end;
$$;


ALTER FUNCTION private.assert_canonical_override_payload(p_payload jsonb, p_require_registered boolean) OWNER TO postgres;

--
-- Name: assert_direct_permission_user(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.assert_direct_permission_user(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
begin
  select u.company_id
    into v_company_id
    from public.users u
   where u.id = p_user_id
     and u.company_id is not null
     and u.deleted_at is null
     and coalesce(u.is_active, false);

  if not found then
    return;
  end if;

  perform private.lock_lead_assignment_company(v_company_id);

  if exists (
    select 1
      from public.user_permission_overrides upo
     where upo.user_id = p_user_id
       and upo.permission = 'spec.admin'
       and not private.is_canonical_internal_permission_override(
         upo.permission,
         upo.company_id,
         upo.scope,
         upo.granted
       )
  ) then
    raise exception 'direct_permission_write_invalid: protected_permission_override_invalid'
      using errcode = '23514';
  end if;

  if exists (
    select 1
      from public.user_permission_overrides upo
     where upo.user_id = p_user_id
       and upo.company_id is distinct from v_company_id
       and not private.is_canonical_internal_permission_override(
         upo.permission,
         upo.company_id,
         upo.scope,
         upo.granted
       )
  ) then
    raise exception 'direct_permission_write_invalid: stale_company_override'
      using errcode = '23514';
  end if;

  begin
    perform private.assert_permission_users_valid(array[p_user_id]);
  exception
    when sqlstate '22023' then
      raise exception using
        errcode = '23514',
        message = 'direct_permission_write_invalid',
        detail = sqlerrm;
  end;

  if exists (
    select 1
      from private.stranded_permission_assignments(
        v_company_id,
        array[p_user_id]
      )
  ) then
    raise exception 'permission_change_would_strand_assignments'
      using errcode = '23514';
  end if;
end;
$$;


ALTER FUNCTION private.assert_direct_permission_user(p_user_id uuid) OWNER TO postgres;

--
-- Name: assert_permission_users_valid(uuid[]); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.assert_permission_users_valid(p_user_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
declare
  v_user record;
  v_issues jsonb;
begin
  for v_user in
    select u.id, u.company_id
      from public.users u
     where u.id = any(coalesce(p_user_ids, array[]::uuid[]))
       and u.deleted_at is null
       and coalesce(u.is_active, false)
     order by u.id
  loop
    v_issues := private.pipeline_dependency_issues_for_user(
      v_user.id,
      v_user.company_id
    );
    if v_issues <> '[]'::jsonb then
      raise exception using
        errcode = '22023',
        message = 'invalid_permission_dependencies',
        detail = jsonb_build_object(
          'user_id', v_user.id,
          'issues', v_issues
        )::text;
    end if;
  end loop;
end;
$$;


ALTER FUNCTION private.assert_permission_users_valid(p_user_ids uuid[]) OWNER TO postgres;

