--
-- Name: bump_agent_operational_read_revision(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.bump_agent_operational_read_revision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
declare
  v_old_company_id uuid;
  v_new_company_id uuid;
begin
  if tg_op in ('UPDATE', 'DELETE') then
    if tg_table_name = 'companies' then
      v_old_company_id := old.id;
    elsif tg_table_name = 'project_photos' then
      v_old_company_id := case
        when pg_input_is_valid(old.company_id::text, 'uuid')
          then old.company_id::text::uuid
        else null
      end;
    else
      v_old_company_id := old.company_id;
    end if;
  end if;

  if tg_op in ('INSERT', 'UPDATE') then
    if tg_table_name = 'companies' then
      v_new_company_id := new.id;
    elsif tg_table_name = 'project_photos' then
      v_new_company_id := case
        when pg_input_is_valid(new.company_id::text, 'uuid')
          then new.company_id::text::uuid
        else null
      end;
    else
      v_new_company_id := new.company_id;
    end if;
  end if;

  if v_old_company_id is not null then
    perform private.advance_agent_operational_read_revision(v_old_company_id);
  end if;

  if v_new_company_id is not null
     and v_new_company_id is distinct from v_old_company_id then
    perform private.advance_agent_operational_read_revision(v_new_company_id);
  end if;

  -- AFTER row-trigger return values are ignored. NULL avoids polymorphic
  -- record coercion and makes that fact explicit.
  return null;
end;
$$;


ALTER FUNCTION private.bump_agent_operational_read_revision() OWNER TO postgres;

--
-- Name: bump_agent_read_domain_revision(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.bump_agent_read_domain_revision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'private', 'pg_temp'
    AS $$
declare
  v_old_row jsonb;
  v_new_row jsonb;
  v_old_company_id uuid;
  v_new_company_id uuid;
begin
  if tg_nargs is distinct from 2
     or nullif(tg_argv[0], '') is null
     or nullif(tg_argv[1], '') is null
     or tg_when is distinct from 'AFTER'
     or tg_level is distinct from 'ROW'
     or tg_op not in ('INSERT', 'UPDATE', 'DELETE') then
    raise exception 'agent_read_domain_revision_trigger_misconfigured'
      using errcode = '55000';
  end if;

  if tg_op in ('UPDATE', 'DELETE') then
    v_old_row := to_jsonb(old);
    if not (v_old_row ? tg_argv[1]) then
      raise exception 'agent_read_domain_revision_trigger_misconfigured'
        using errcode = '55000';
    end if;
    v_old_company_id := private.agent_read_domain_uuid_from_text(
      v_old_row ->> tg_argv[1]
    );
  end if;

  if tg_op in ('INSERT', 'UPDATE') then
    v_new_row := to_jsonb(new);
    if not (v_new_row ? tg_argv[1]) then
      raise exception 'agent_read_domain_revision_trigger_misconfigured'
        using errcode = '55000';
    end if;
    v_new_company_id := private.agent_read_domain_uuid_from_text(
      v_new_row ->> tg_argv[1]
    );
  end if;

  perform private.advance_agent_read_domain_revisions(
    array[v_old_company_id, v_new_company_id],
    tg_argv[0]
  );

  -- AFTER row-trigger return values are ignored. NULL avoids polymorphic
  -- record coercion and makes that behavior explicit.
  return null;
end;
$$;


ALTER FUNCTION private.bump_agent_read_domain_revision() OWNER TO postgres;

--
-- Name: bump_agent_site_visit_workflow_revision(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.bump_agent_site_visit_workflow_revision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare prior_company uuid;next_company uuid;
begin
 if tg_op<>'INSERT' then prior_company:=private.try_parse_uuid(to_jsonb(old)->>'company_id');end if;
 if tg_op<>'DELETE' then next_company:=private.try_parse_uuid(to_jsonb(new)->>'company_id');end if;
 if tg_table_schema='public' and tg_table_name='companies' then
  if tg_op<>'INSERT' then prior_company:=old.id;end if;
  if tg_op<>'DELETE' then next_company:=new.id;end if;
 end if;
 insert into private.agent_site_visit_workflow_revisions(company_id,revision)
 select company,1 from (select distinct unnest(array[prior_company,next_company]) company) x where company is not null order by company
 on conflict(company_id) do update set revision=private.agent_site_visit_workflow_revisions.revision+1;
 return coalesce(new,old);
end $$;


ALTER FUNCTION private.bump_agent_site_visit_workflow_revision() OWNER TO postgres;

--
-- Name: bump_agent_work_queue_source_revision(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.bump_agent_work_queue_source_revision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_old jsonb;
  v_new jsonb;
  v_fields text[];
  v_changed boolean := true;
  v_company_ids uuid[];
  v_old_project_company_id uuid;
  v_new_project_company_id uuid;
begin
  if tg_when is distinct from 'AFTER'
     or tg_level is distinct from 'ROW'
     or tg_nargs is distinct from 0
     or tg_table_schema is distinct from 'public'
     or tg_table_name not in (
       'activities','email_connections','email_threads','opportunities',
       'projects','project_tasks','project_notes'
     )
     or tg_op not in ('INSERT', 'UPDATE', 'DELETE') then
    raise exception 'agent_work_queue_revision_trigger_misconfigured'
      using errcode = '55000';
  end if;

  if tg_op in ('UPDATE', 'DELETE') then v_old := pg_catalog.to_jsonb(old); end if;
  if tg_op in ('INSERT', 'UPDATE') then v_new := pg_catalog.to_jsonb(new); end if;

  v_fields := case tg_table_name
    when 'activities' then array[
      'id', 'company_id', 'type', 'created_at', 'email_connection_id',
      'email_thread_id', 'opportunity_id', 'project_id', 'match_needs_review'
    ]
    when 'email_connections' then array[
      'id','company_id','type','user_id'
    ]
    when 'email_threads' then array[
      'id', 'company_id', 'connection_id', 'opportunity_id',
      'provider_thread_id', 'archived_at', 'next_commitment_due_at',
      'has_unresolved_commitments','subject','latest_snippet',
      'last_message_at','unread_count','snoozed_until'
    ]
    when 'opportunities' then array[
      'id', 'company_id', 'stage', 'archived_at', 'deleted_at',
      'merged_into_opportunity_id', 'next_follow_up_at',
      'operator_action_required_at','assigned_to'
    ]
    when 'projects' then array[
      'id','company_id','deleted_at'
    ]
    when 'project_tasks' then array[
      'id','company_id','project_id','deleted_at','team_member_ids'
    ]
    else array[
      'id','company_id','project_id','deleted_at','mentioned_user_ids'
    ]
  end;

  if tg_op = 'UPDATE' then
    select coalesce(pg_catalog.bool_or(v_old -> field is distinct from v_new -> field), false)
      into v_changed
    from pg_catalog.unnest(v_fields) field;
  end if;
  if not v_changed then return null; end if;

  v_company_ids := array[
    private.agent_read_domain_uuid_from_text(v_old ->> 'company_id'),
    private.agent_read_domain_uuid_from_text(v_new ->> 'company_id')
  ];
  if tg_table_name in ('project_tasks','project_notes') then
    select project.company_id into v_old_project_company_id
    from public.projects project
    where project.id=private.agent_read_domain_uuid_from_text(
      v_old ->> 'project_id'
    );
    select project.company_id into v_new_project_company_id
    from public.projects project
    where project.id=private.agent_read_domain_uuid_from_text(
      v_new ->> 'project_id'
    );
    v_company_ids := v_company_ids || array[
      v_old_project_company_id,v_new_project_company_id
    ];
  end if;
  perform private.advance_agent_read_domain_revisions(v_company_ids, 'work_queue');
  return null;
end;
$$;


ALTER FUNCTION private.bump_agent_work_queue_source_revision() OWNER TO postgres;

--
-- Name: canonical_user_override_snapshot(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.canonical_user_override_snapshot(p_user_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'permission', upo.permission,
        'scope', upo.scope,
        'granted', upo.granted
      )
      order by upo.permission, upo.scope nulls first, upo.granted
    ),
    '[]'::jsonb
  )
  from public.user_permission_overrides upo
  where upo.user_id = p_user_id;
$$;


ALTER FUNCTION private.canonical_user_override_snapshot(p_user_id uuid) OWNER TO postgres;

--
-- Name: canonicalize_address_text(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.canonicalize_address_text(p_address text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'private'
    AS $$
  with cleaned as (
    select btrim(
      regexp_replace(
        regexp_replace(lower(coalesce(p_address, '')), '[.,]', ' ', 'g'),
        '\s+',
        ' ',
        'g'
      )
    ) as value
  ),
  tokens as (
    select token, ordinality
      from cleaned,
      regexp_split_to_table(cleaned.value, '\s+')
        with ordinality as source(token, ordinality)
     where token <> ''
  )
  select coalesce(
    string_agg(
      case token
        when 'w' then 'west'
        when 'e' then 'east'
        when 'n' then 'north'
        when 's' then 'south'
        when 'nw' then 'northwest'
        when 'ne' then 'northeast'
        when 'sw' then 'southwest'
        when 'se' then 'southeast'
        when 'ave' then 'avenue'
        when 'av' then 'avenue'
        when 'st' then 'street'
        when 'str' then 'street'
        when 'rd' then 'road'
        when 'blvd' then 'boulevard'
        when 'boul' then 'boulevard'
        when 'dr' then 'drive'
        when 'cres' then 'crescent'
        when 'cr' then 'crescent'
        when 'hwy' then 'highway'
        when 'pl' then 'place'
        when 'ct' then 'court'
        when 'cir' then 'circle'
        when 'ln' then 'lane'
        when 'ter' then 'terrace'
        when 'trl' then 'trail'
        when 'wy' then 'way'
        when 'pkwy' then 'parkway'
        when 'sq' then 'square'
        else token
      end,
      ' ' order by ordinality
    ),
    ''
  )
  from tokens;
$$;


ALTER FUNCTION private.canonicalize_address_text(p_address text) OWNER TO postgres;

--
-- Name: change_assignment_system_company_serialized_internal(uuid, bigint, uuid, uuid, text, uuid, uuid, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.change_assignment_system_company_serialized_internal(p_opportunity_id uuid, p_expected_assignment_version bigint, p_expected_assigned_to uuid, p_new_assigned_to uuid, p_system_source text, p_actor_user_id uuid DEFAULT NULL::uuid, p_suggestion_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'access_denied'
      using errcode = '42501';
  end if;

  if p_system_source is null or p_system_source not in (
    'personal_mailbox',
    'company_mailbox_default',
    'external_intake_default',
    'public_booking_default',
    'deactivation',
    'permission_change',
    'admin_correction',
    'system_repair'
  ) then
    raise exception 'invalid_system_assignment_source'
      using errcode = '22023';
  end if;

  select opportunity.company_id
  into v_company_id
  from public.opportunities opportunity
  where opportunity.id = p_opportunity_id
    and opportunity.deleted_at is null;

  if not found then
    raise exception 'opportunity_not_found'
      using errcode = 'P0002';
  end if;

  if p_actor_user_id is not null
    and not exists (
      select 1
      from public.users actor
      where actor.id = p_actor_user_id
        and actor.company_id = v_company_id
        and actor.deleted_at is null
        and coalesce(actor.is_active, false)
    )
  then
    raise exception 'assignment_actor_ineligible'
      using errcode = '22023';
  end if;

  return private.change_opportunity_assignment_core(
    p_opportunity_id,
    p_expected_assignment_version,
    p_expected_assigned_to,
    p_new_assigned_to,
    p_system_source,
    p_actor_user_id,
    v_company_id,
    true,
    p_suggestion_id,
    coalesce(p_metadata, '{}'::jsonb)
  );
end;
$$;


ALTER FUNCTION private.change_assignment_system_company_serialized_internal(p_opportunity_id uuid, p_expected_assignment_version bigint, p_expected_assigned_to uuid, p_new_assigned_to uuid, p_system_source text, p_actor_user_id uuid, p_suggestion_id uuid, p_metadata jsonb) OWNER TO postgres;

--
-- Name: change_opportunity_assignment_core(uuid, bigint, uuid, uuid, text, uuid, uuid, boolean, uuid, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.change_opportunity_assignment_core(p_opportunity_id uuid, p_expected_assignment_version bigint, p_expected_assigned_to uuid, p_new_assigned_to uuid, p_source text, p_actor_user_id uuid, p_actor_company_id uuid, p_is_system boolean, p_suggestion_id uuid, p_metadata jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
declare
  v_opportunity public.opportunities%rowtype;
  v_scope text;
  v_event_id uuid;
  v_new_version bigint;
  v_new_notify boolean;
  v_previous_access_after boolean;
begin
  if p_opportunity_id is null
    or p_expected_assignment_version is null
    or p_expected_assignment_version < 0
  then
    raise exception 'invalid_assignment_expectation'
      using errcode = '22023';
  end if;

  if p_metadata is null or jsonb_typeof(p_metadata) <> 'object' then
    raise exception 'assignment_metadata_must_be_object'
      using errcode = '22023';
  end if;

  if p_is_system is null then
    raise exception 'assignment_principal_kind_required'
      using errcode = '22023';
  elsif p_is_system then
    if p_source not in (
      'agent_customer_update',
      'personal_mailbox',
      'company_mailbox_default',
      'external_intake_default',
      'public_booking_default',
      'deactivation',
      'permission_change',
      'admin_correction',
      'system_repair'
    ) then
      raise exception 'invalid_system_assignment_source'
        using errcode = '22023';
    end if;
  elsif p_source is null
    or p_source not in ('manual', 'suggestion_accept')
  then
    raise exception 'invalid_human_assignment_source'
      using errcode = '22023';
  end if;

  select opportunity.*
  into v_opportunity
  from public.opportunities opportunity
  where opportunity.id = p_opportunity_id
  for update;

  if not found or v_opportunity.deleted_at is not null then
    raise exception 'opportunity_not_found'
      using errcode = 'P0002';
  end if;

  if p_actor_company_id is distinct from v_opportunity.company_id then
    raise exception 'access_denied'
      using errcode = '42501';
  end if;

  if p_actor_user_id is not null then
    perform 1
    from public.users actor
    where actor.id = p_actor_user_id
      and actor.company_id = v_opportunity.company_id
      and actor.deleted_at is null
      and coalesce(actor.is_active, false)
    for share;
    if not found then
      raise exception 'assignment_actor_ineligible'
        using errcode = '42501';
    end if;
  end if;

  if not p_is_system then
    if p_actor_user_id is null then
      raise exception 'access_denied'
        using errcode = '42501';
    end if;

    v_scope := private.current_user_scope_for('pipeline.assign');
    if v_scope is null
      and private.should_use_pipeline_manage_compat(
        p_actor_user_id,
        p_actor_company_id,
        'pipeline.assign'
      )
    then
      v_scope := 'all';
    end if;

    if v_scope is null or v_scope not in ('all', 'assigned') then
      raise exception 'access_denied'
        using errcode = '42501';
    end if;

    if v_scope = 'assigned'
      and v_opportunity.assigned_to is distinct from p_actor_user_id
    then
      raise exception 'assignment_access_lost'
        using errcode = '42501';
    end if;
  end if;

  if v_opportunity.assignment_version
      is distinct from p_expected_assignment_version
    or v_opportunity.assigned_to is distinct from p_expected_assigned_to
  then
    return jsonb_build_object(
      'ok', false,
      'conflict', true,
      'assigned_to', v_opportunity.assigned_to,
      'assignment_version', v_opportunity.assignment_version,
      'event_id', null
    );
  end if;

  if v_opportunity.assigned_to is not distinct from p_new_assigned_to then
    return jsonb_build_object(
      'ok', true,
      'conflict', false,
      'assigned_to', v_opportunity.assigned_to,
      'assignment_version', v_opportunity.assignment_version,
      'event_id', null
    );
  end if;

  if not p_is_system and v_scope = 'assigned' then
    if p_new_assigned_to is null then
      raise exception 'assigned_scope_cannot_unassign'
        using errcode = '42501';
    end if;
    if v_opportunity.archived_at is not null
      or v_opportunity.stage in ('won', 'lost', 'discarded')
    then
      raise exception 'assigned_scope_terminal_transfer_forbidden'
        using errcode = '42501';
    end if;
  end if;

  if p_new_assigned_to is not null then
    perform 1
    from public.users target
    where target.id = p_new_assigned_to
      and target.company_id = v_opportunity.company_id
      and target.deleted_at is null
      and coalesce(target.is_active, false)
      and public.has_permission(
        p_new_assigned_to,
        'pipeline.view',
        'assigned'
      )
    for share;
    if not found then
      raise exception 'assignment_target_ineligible'
        using errcode = '22023';
    end if;
  end if;

  if p_source = 'suggestion_accept' then
    if p_suggestion_id is null
      or not exists (
        select 1
        from public.opportunity_assignment_suggestions suggestion
        where suggestion.id = p_suggestion_id
          and suggestion.company_id = v_opportunity.company_id
          and suggestion.opportunity_id = p_opportunity_id
          and suggestion.suggested_user_id = p_new_assigned_to
          and suggestion.resolution_state = 'pending'
      )
    then
      raise exception 'assignment_suggestion_invalid'
        using errcode = '22023';
    end if;
  elsif p_suggestion_id is not null then
    raise exception 'suggestion_id_requires_suggestion_accept'
      using errcode = '22023';
  end if;

  v_new_version := v_opportunity.assignment_version + 1;

  insert into private.opportunity_assignment_write_tokens (
    transaction_id,
    backend_pid,
    opportunity_id,
    operation,
    assigned_to,
    assignment_version
  ) values (
    txid_current(),
    pg_backend_pid(),
    p_opportunity_id,
    'update',
    p_new_assigned_to,
    v_new_version
  );

  update public.opportunities
  set assigned_to = p_new_assigned_to,
      assignment_version = assignment_version + 1,
      updated_at = now()
  where id = p_opportunity_id
  returning assignment_version into v_new_version;

  insert into public.opportunity_assignment_events (
    company_id,
    opportunity_id,
    previous_assignee_id,
    new_assignee_id,
    actor_user_id,
    source,
    suggestion_id,
    assignment_version,
    previous_assignee_snapshot,
    new_assignee_snapshot,
    actor_snapshot,
    metadata
  ) values (
    v_opportunity.company_id,
    p_opportunity_id,
    v_opportunity.assigned_to,
    p_new_assigned_to,
    p_actor_user_id,
    p_source,
    p_suggestion_id,
    v_new_version,
    private.user_assignment_snapshot(v_opportunity.assigned_to),
    private.user_assignment_snapshot(p_new_assigned_to),
    private.user_assignment_snapshot(p_actor_user_id),
    p_metadata
  )
  returning id into v_event_id;

  update public.opportunity_assignment_suggestions
  set resolution_state = case
        when id = p_suggestion_id and p_source = 'suggestion_accept'
          then 'accepted'
        else 'superseded'
      end,
      resolved_at = now(),
      resolved_by = p_actor_user_id,
      resolution_event_id = v_event_id,
      resolution_metadata = jsonb_build_object(
        'assignment_source', p_source,
        'assignment_version', v_new_version
      ),
      updated_at = now()
  where company_id = v_opportunity.company_id
    and opportunity_id = p_opportunity_id
    and resolution_state = 'pending';

  if v_opportunity.assigned_to is not null
    and v_opportunity.assigned_to is distinct from p_new_assigned_to
  then
    v_previous_access_after := exists (
      select 1
      from public.users prior_user
      where prior_user.id = v_opportunity.assigned_to
        and prior_user.company_id = v_opportunity.company_id
        and prior_user.deleted_at is null
        and coalesce(prior_user.is_active, false)
        and (
          public.has_permission(
            v_opportunity.assigned_to,
            'pipeline.view',
            'all'
          )
          or private.should_use_pipeline_manage_compat(
            v_opportunity.assigned_to,
            v_opportunity.company_id,
            'pipeline.view'
          )
        )
    );

    insert into public.opportunity_assignment_deliveries (
      assignment_event_id,
      company_id,
      opportunity_id,
      assignment_version,
      recipient_user_id,
      access_after,
      notify
    ) values (
      v_event_id,
      v_opportunity.company_id,
      p_opportunity_id,
      v_new_version,
      v_opportunity.assigned_to,
      v_previous_access_after,
      false
    )
    on conflict (assignment_event_id, recipient_user_id) do nothing;
  end if;

  if p_new_assigned_to is not null
    and p_new_assigned_to is distinct from v_opportunity.assigned_to
  then
    v_new_notify := not (
      not p_is_system
      and p_new_assigned_to = p_actor_user_id
    );

    insert into public.opportunity_assignment_deliveries (
      assignment_event_id,
      company_id,
      opportunity_id,
      assignment_version,
      recipient_user_id,
      access_after,
      notify
    ) values (
      v_event_id,
      v_opportunity.company_id,
      p_opportunity_id,
      v_new_version,
      p_new_assigned_to,
      true,
      v_new_notify
    )
    on conflict (assignment_event_id, recipient_user_id) do nothing;
  end if;

  return jsonb_build_object(
    'ok', true,
    'conflict', false,
    'assigned_to', p_new_assigned_to,
    'assignment_version', v_new_version,
    'event_id', v_event_id
  );
end;
$$;


ALTER FUNCTION private.change_opportunity_assignment_core(p_opportunity_id uuid, p_expected_assignment_version bigint, p_expected_assigned_to uuid, p_new_assigned_to uuid, p_source text, p_actor_user_id uuid, p_actor_company_id uuid, p_is_system boolean, p_suggestion_id uuid, p_metadata jsonb) OWNER TO postgres;

--
-- Name: current_user_scope_for(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.current_user_scope_for(p_permission text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
  select private.effective_permission_scope_for_user(
    private.get_current_user_id(),
    private.get_user_company_id(),
    p_permission
  );
$$;


ALTER FUNCTION private.current_user_scope_for(p_permission text) OWNER TO postgres;

--
-- Name: effective_inbox_scope_for_user(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.effective_inbox_scope_for_user(p_actor_user_id uuid, p_actor_company_id uuid, p_permission text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
begin
  if p_permission is null
    or p_permission not in ('inbox.view', 'inbox.send')
    or not exists (
      select 1
        from public.users u
       where u.id = p_actor_user_id
         and u.company_id = p_actor_company_id
         and u.deleted_at is null
         and coalesce(u.is_active, false)
    )
  then
    return null;
  end if;

  if public.has_permission(p_actor_user_id, p_permission, 'all') then
    return 'all';
  end if;
  if public.has_permission(p_actor_user_id, p_permission, 'assigned') then
    return 'assigned';
  end if;
  if p_permission = 'inbox.view'
    and public.has_permission(p_actor_user_id, p_permission, 'own')
  then
    return 'own';
  end if;
  if p_permission = 'inbox.view'
    and private.should_use_inbox_view_company_compat(
      p_actor_user_id,
      p_actor_company_id
    )
  then
    return 'all';
  end if;
  return null;
end;
$$;


ALTER FUNCTION private.effective_inbox_scope_for_user(p_actor_user_id uuid, p_actor_company_id uuid, p_permission text) OWNER TO postgres;

--
-- Name: effective_permission_scope_for_user(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.effective_permission_scope_for_user(p_actor_user_id uuid, p_actor_company_id uuid, p_permission text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
begin
  if p_permission in (
    'pipeline.create',
    'pipeline.view',
    'pipeline.edit',
    'pipeline.assign',
    'pipeline.convert'
  ) then
    return private.effective_pipeline_scope_for_user(
      p_actor_user_id,
      p_actor_company_id,
      p_permission
    );
  end if;

  if p_permission in ('inbox.view', 'inbox.send') then
    return private.effective_inbox_scope_for_user(
      p_actor_user_id,
      p_actor_company_id,
      p_permission
    );
  end if;

  return private.raw_permission_scope_for_user(
    p_actor_user_id,
    p_actor_company_id,
    p_permission
  );
end;
$$;


ALTER FUNCTION private.effective_permission_scope_for_user(p_actor_user_id uuid, p_actor_company_id uuid, p_permission text) OWNER TO postgres;

--
-- Name: effective_pipeline_scope_for_user(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.effective_pipeline_scope_for_user(p_actor_user_id uuid, p_actor_company_id uuid, p_permission text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
declare
  v_raw_scope text;
  v_prerequisite_scope text;
begin
  if p_permission is null or p_permission not in (
    'pipeline.create',
    'pipeline.view',
    'pipeline.edit',
    'pipeline.assign',
    'pipeline.convert'
  ) then
    return null;
  end if;

  if not exists (
    select 1
      from public.users u
     where u.id = p_actor_user_id
       and u.company_id = p_actor_company_id
       and u.deleted_at is null
       and coalesce(u.is_active, false)
  ) then
    return null;
  end if;

  if public.has_permission(p_actor_user_id, p_permission, 'all') then
    v_raw_scope := 'all';
  elsif public.has_permission(p_actor_user_id, p_permission, 'assigned') then
    v_raw_scope := 'assigned';
  elsif private.should_use_pipeline_manage_compat(
    p_actor_user_id,
    p_actor_company_id,
    p_permission
  ) then
    v_raw_scope := 'all';
  else
    return null;
  end if;

  -- `own` and every unknown scope are invalid for these capabilities.
  if v_raw_scope not in ('all', 'assigned') then
    return null;
  end if;

  case p_permission
    when 'pipeline.create' then
      if v_raw_scope is distinct from 'all' then
        return null;
      end if;
      v_prerequisite_scope := private.effective_pipeline_scope_for_user(
        p_actor_user_id,
        p_actor_company_id,
        'pipeline.view'
      );
      if v_prerequisite_scope not in ('all', 'assigned') then
        return null;
      end if;
      return 'all';

    when 'pipeline.view' then
      return v_raw_scope;

    when 'pipeline.edit' then
      v_prerequisite_scope := private.effective_pipeline_scope_for_user(
        p_actor_user_id,
        p_actor_company_id,
        'pipeline.view'
      );
      return private.least_permissive_pipeline_scope(
        v_raw_scope,
        v_prerequisite_scope
      );

    when 'pipeline.assign' then
      v_prerequisite_scope := private.effective_pipeline_scope_for_user(
        p_actor_user_id,
        p_actor_company_id,
        'pipeline.edit'
      );
      return private.least_permissive_pipeline_scope(
        v_raw_scope,
        v_prerequisite_scope
      );

    when 'pipeline.convert' then
      v_prerequisite_scope := private.effective_pipeline_scope_for_user(
        p_actor_user_id,
        p_actor_company_id,
        'pipeline.edit'
      );
      return private.least_permissive_pipeline_scope(
        v_raw_scope,
        v_prerequisite_scope
      );
  end case;

  return null;
end;
$$;


ALTER FUNCTION private.effective_pipeline_scope_for_user(p_actor_user_id uuid, p_actor_company_id uuid, p_permission text) OWNER TO postgres;

--
-- Name: email_assignment_contact_form_draft_canonical_recipient(uuid, uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.email_assignment_contact_form_draft_canonical_recipient(p_company_id uuid, p_opportunity_id uuid, p_source_activity_id uuid, p_connection_id uuid, p_provider_message_id text, p_provider_thread_id text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_opportunity_email text;
  v_client_email text;
  v_client_id uuid;
  v_client_ref uuid;
  v_legacy_client_id uuid;
  v_source_sender text;
  v_canonical_email text;
begin
  if p_company_id is null
     or p_opportunity_id is null
     or p_source_activity_id is null
     or p_connection_id is null
     or nullif(btrim(coalesce(p_provider_message_id, '')), '') is null
     or nullif(btrim(coalesce(p_provider_thread_id, '')), '') is null then
    return null;
  end if;

  select
    nullif(lower(btrim(coalesce(opportunity.contact_email, ''))), ''),
    nullif(lower(btrim(coalesce(client.email, ''))), ''),
    client.id,
    opportunity.client_ref,
    opportunity.client_id,
    nullif(lower(btrim(coalesce(activity.from_email, ''))), '')
    into
      v_opportunity_email,
      v_client_email,
      v_client_id,
      v_client_ref,
      v_legacy_client_id,
      v_source_sender
  from public.opportunities opportunity
  join public.activities activity
    on activity.id = p_source_activity_id
   and activity.company_id = p_company_id
   and activity.opportunity_id = p_opportunity_id
   and activity.email_connection_id = p_connection_id
   and activity.email_message_id = p_provider_message_id
   and activity.email_thread_id = p_provider_thread_id
   and activity.type = 'email'
   and activity.direction = 'inbound'
   and not coalesce(activity.match_needs_review, false)
   and nullif(btrim(coalesce(activity.from_email, '')), '') is not null
   and nullif(btrim(coalesce(activity.body_text, '')), '') is not null
  left join public.clients client
    on client.id = coalesce(opportunity.client_ref, opportunity.client_id)
   and client.company_id = p_company_id
   and client.deleted_at is null
  where opportunity.id = p_opportunity_id
    and opportunity.company_id = p_company_id;
  if not found then
    return null;
  end if;

  if v_client_ref is not null
     and v_legacy_client_id is not null
     and v_client_ref <> v_legacy_client_id then
    return null;
  end if;

  -- Opportunity identity is authoritative. The active linked client is only a
  -- fallback when the opportunity email is blank; disagreement fails closed.
  if v_opportunity_email is not null
     and v_opportunity_email !~
       '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
    return null;
  end if;
  if v_client_email is not null
     and v_client_email !~
       '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
    return null;
  end if;
  if v_opportunity_email is not null
     and v_client_email is not null
     and v_opportunity_email <> v_client_email then
    return null;
  end if;

  v_canonical_email := coalesce(v_opportunity_email, v_client_email);
  if v_canonical_email is null
     or v_canonical_email !~
       '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
     or v_source_sender is null
     or v_source_sender !~
       '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
    return null;
  end if;

  -- Modern ingestion has already replaced a trusted wrapper with the parsed
  -- submitter. Preserve that exact, already-deployed proof path.
  if v_source_sender = v_canonical_email then
    return v_canonical_email;
  end if;

  -- A retained wrapper is accepted only with immutable service attestation for
  -- this exact activity, connection, lead, provider identity, and recipient.
  -- Editable public provenance is deliberately never an authorization input.
  if exists (
    select 1
    from private.email_contact_form_recipient_attestations attestation
    where attestation.source_activity_id = p_source_activity_id
      and attestation.company_id = p_company_id
      and attestation.opportunity_id = p_opportunity_id
      and attestation.connection_id = p_connection_id
      and attestation.provider_message_id = p_provider_message_id
      and attestation.provider_thread_id = p_provider_thread_id
      and attestation.canonical_recipient = v_canonical_email
  ) then
    return v_canonical_email;
  end if;

  return null;
end;
$_$;


ALTER FUNCTION private.email_assignment_contact_form_draft_canonical_recipient(p_company_id uuid, p_opportunity_id uuid, p_source_activity_id uuid, p_connection_id uuid, p_provider_message_id text, p_provider_thread_id text) OWNER TO postgres;

--
-- Name: email_assignment_contact_form_draft_has_reply(uuid, uuid, uuid, timestamp with time zone, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.email_assignment_contact_form_draft_has_reply(p_company_id uuid, p_opportunity_id uuid, p_connection_id uuid, p_source_occurred_at timestamp with time zone, p_customer_email text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    p_company_id is null
    or p_opportunity_id is null
    or p_connection_id is null
    or p_source_occurred_at is null
    or nullif(lower(btrim(coalesce(p_customer_email, ''))), '') is null
    or exists (
      select 1
      from public.opportunity_correspondence_events reply
      where reply.company_id = p_company_id
        and reply.opportunity_id = p_opportunity_id
        and reply.direction = 'outbound'
        and reply.party_role = 'ops'
        and reply.is_meaningful
        and reply.occurred_at > p_source_occurred_at
        and exists (
          select 1
          from unnest(reply.to_emails || reply.cc_emails) recipient(email)
          where lower(btrim(recipient.email)) =
            lower(btrim(p_customer_email))
        )
    )
    or exists (
      select 1
      from public.activities reply_activity
      where reply_activity.company_id = p_company_id
        and reply_activity.opportunity_id = p_opportunity_id
        and reply_activity.type = 'email'
        and reply_activity.direction = 'outbound'
        and reply_activity.created_at > p_source_occurred_at
        and nullif(btrim(coalesce(reply_activity.email_message_id, '')), '')
          is not null
        and nullif(btrim(coalesce(reply_activity.body_text, '')), '') is not null
        and exists (
          select 1
          from unnest(
            coalesce(reply_activity.to_emails, '{}'::text[]) ||
            coalesce(reply_activity.cc_emails, '{}'::text[])
          ) recipient(email)
          where lower(btrim(recipient.email)) =
            lower(btrim(p_customer_email))
        )
    );
$$;


ALTER FUNCTION private.email_assignment_contact_form_draft_has_reply(p_company_id uuid, p_opportunity_id uuid, p_connection_id uuid, p_source_occurred_at timestamp with time zone, p_customer_email text) OWNER TO postgres;

--
-- Name: email_contact_form_source_markers_present(text, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.email_contact_form_source_markers_present(p_subject text, p_body text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
  select
    p_subject !~* '^[[:space:]]*re[[:space:]]*:'
    and (
      p_body ~*
        '\y(submission summary|site visitor just submitted your form|submitted your form|new contact form submission|contact form submission|view submissions|this email was sent as a notification from this site)\y'
      or (
        p_subject ~*
          '\y(got a new submission|new form entry|new contact form|new submission|form submission|new inquiry|new lead|contact us form|quote request|free quote form)\y'
        and p_body ~*
          '(?n)^>?[[:space:]]*(email|email address|e-mail|e-mail address|your email|reply-to)[[:space:]]*:'
      )
    );
$$;


ALTER FUNCTION private.email_contact_form_source_markers_present(p_subject text, p_body text) OWNER TO postgres;

--
-- Name: enforce_permission_assignment_resolutions(uuid, uuid, uuid[], jsonb, text, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enforce_permission_assignment_resolutions(p_actor_user_id uuid, p_company_id uuid, p_affected_user_ids uuid[], p_assignment_resolutions jsonb, p_mutation_kind text, p_subject_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $_$
declare
  v_resolutions jsonb := coalesce(p_assignment_resolutions, '[]'::jsonb);
  v_stranded_ids uuid[] := array[]::uuid[];
  v_stranded_count integer := 0;
  v_safe_stranded jsonb := '[]'::jsonb;
  v_eligible_assignees jsonb := '[]'::jsonb;
  v_actor_can_assign_all boolean;
  v_actor_can_view_all boolean;
  v_item jsonb;
  v_opportunity_id uuid;
  v_expected_assigned_to uuid;
  v_expected_assignment_version bigint;
  v_new_assigned_to uuid;
  v_current_found boolean;
  v_current_assigned_to uuid;
  v_current_assignment_version bigint;
  v_result jsonb;
  v_applied integer := 0;
begin
  if jsonb_typeof(v_resolutions) <> 'array' then
    raise exception 'invalid_assignment_resolutions'
      using errcode = '22023';
  end if;

  -- Lock active responsibility rows in stable order before deriving the exact
  -- stranded set. Terminal assignments remain historical and are untouched.
  perform 1
    from public.opportunities o
   where o.company_id = p_company_id
     and o.assigned_to = any(coalesce(p_affected_user_ids, array[]::uuid[]))
     and o.deleted_at is null
     and o.archived_at is null
     and o.stage not in ('won', 'lost', 'discarded')
   order by o.id
   for update;

  select
    coalesce(array_agg(s.opportunity_id order by s.opportunity_id), array[]::uuid[]),
    count(*)::integer
    into v_stranded_ids, v_stranded_count
    from private.stranded_permission_assignments(
      p_company_id,
      p_affected_user_ids
    ) s;

  v_actor_can_assign_all := private.effective_pipeline_scope_for_user(
    p_actor_user_id,
    p_company_id,
    'pipeline.assign'
  ) = 'all';
  v_actor_can_view_all := private.effective_pipeline_scope_for_user(
    p_actor_user_id,
    p_company_id,
    'pipeline.view'
  ) = 'all';

  if v_actor_can_view_all then
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'opportunity_id', s.opportunity_id,
          'title', s.title,
          'assigned_to', s.assigned_to,
          'assignment_version', s.assignment_version
        )
        order by s.opportunity_id
      ),
      '[]'::jsonb
    )
      into v_safe_stranded
      from private.stranded_permission_assignments(
        p_company_id,
        p_affected_user_ids
      ) s;
  end if;

  if v_actor_can_assign_all and v_actor_can_view_all then
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', u.id,
          'first_name', u.first_name,
          'last_name', u.last_name,
          'profile_image_url', u.profile_image_url,
          'user_color', u.user_color,
          'role', u.role
        )
        order by u.first_name, u.last_name, u.id
      ),
      '[]'::jsonb
    )
      into v_eligible_assignees
      from public.users u
     where u.company_id = p_company_id
       and u.deleted_at is null
       and coalesce(u.is_active, false)
       and private.user_is_guarded_assignment_target_eligible(
         u.id,
         p_company_id
       );
  end if;

  if v_stranded_count > 0 and jsonb_array_length(v_resolutions) = 0 then
    raise exception using
      errcode = '40001',
      message = 'assignment_resolution_required',
      detail = jsonb_build_object(
        'code', 'assignment_resolution_required',
        'stranded_count', v_stranded_count,
        'stranded', v_safe_stranded,
        'eligible_assignees', v_eligible_assignees
      )::text;
  end if;

  if v_stranded_count = 0 and jsonb_array_length(v_resolutions) > 0 then
    raise exception using
      errcode = '22023',
      message = 'extra_resolution',
      detail = jsonb_build_object('stranded_count', 0)::text;
  end if;

  if jsonb_array_length(v_resolutions) > 0 and not v_actor_can_assign_all then
    raise exception 'access_denied: pipeline.assign all required for responsibility resolution'
      using errcode = '42501';
  end if;

  for v_item in select value from jsonb_array_elements(v_resolutions)
  loop
    if jsonb_typeof(v_item) <> 'object'
      or not (
        v_item ?& array[
          'opportunity_id',
          'expected_assigned_to',
          'expected_assignment_version',
          'new_assigned_to'
        ]
      )
      or (select count(*) from jsonb_object_keys(v_item)) <> 4
      or jsonb_typeof(v_item -> 'opportunity_id') <> 'string'
      or jsonb_typeof(v_item -> 'expected_assigned_to') <> 'string'
      or jsonb_typeof(v_item -> 'expected_assignment_version') <> 'number'
      or jsonb_typeof(v_item -> 'new_assigned_to') not in ('string', 'null')
      or (v_item ->> 'expected_assignment_version') !~ '^[0-9]+$'
    then
      raise exception 'invalid_assignment_resolutions'
        using errcode = '22023';
    end if;

    v_opportunity_id := private.permission_try_parse_uuid(
      v_item ->> 'opportunity_id'
    );
    v_expected_assigned_to := private.permission_try_parse_uuid(
      v_item ->> 'expected_assigned_to'
    );
    v_expected_assignment_version := (
      v_item ->> 'expected_assignment_version'
    )::bigint;
    v_new_assigned_to := case
      when jsonb_typeof(v_item -> 'new_assigned_to') = 'null' then null
      else private.permission_try_parse_uuid(v_item ->> 'new_assigned_to')
    end;

    if v_opportunity_id is null
      or v_expected_assigned_to is null
      or (
        jsonb_typeof(v_item -> 'new_assigned_to') = 'string'
        and v_new_assigned_to is null
      )
    then
      raise exception 'invalid_assignment_resolutions'
        using errcode = '22023';
    end if;

    if v_new_assigned_to is not distinct from v_expected_assigned_to then
      raise exception 'no_op_resolution'
        using errcode = '22023';
    end if;
  end loop;

  if (
    select count(*)
      from jsonb_array_elements(v_resolutions)
  ) <> (
    select count(distinct private.permission_try_parse_uuid(
      entry ->> 'opportunity_id'
    ))
      from jsonb_array_elements(v_resolutions) entry
  ) then
    raise exception 'duplicate_resolution'
      using errcode = '22023';
  end if;

  if exists (
    select 1
      from unnest(v_stranded_ids) stranded_id
     where not exists (
       select 1
         from jsonb_array_elements(v_resolutions) entry
        where private.permission_try_parse_uuid(
          entry ->> 'opportunity_id'
        ) = stranded_id
     )
  ) then
    raise exception 'missing_resolution'
      using errcode = '22023';
  end if;

  if exists (
    select 1
      from jsonb_array_elements(v_resolutions) entry
     where not (
       private.permission_try_parse_uuid(entry ->> 'opportunity_id')
       = any(v_stranded_ids)
     )
  ) then
    raise exception 'extra_resolution'
      using errcode = '22023';
  end if;

  for v_item in
    select entry
      from jsonb_array_elements(v_resolutions) entry
     order by private.permission_try_parse_uuid(entry ->> 'opportunity_id')
  loop
    v_opportunity_id := private.permission_try_parse_uuid(
      v_item ->> 'opportunity_id'
    );
    v_expected_assigned_to := private.permission_try_parse_uuid(
      v_item ->> 'expected_assigned_to'
    );
    v_expected_assignment_version := (
      v_item ->> 'expected_assignment_version'
    )::bigint;
    v_new_assigned_to := case
      when jsonb_typeof(v_item -> 'new_assigned_to') = 'null' then null
      else private.permission_try_parse_uuid(v_item ->> 'new_assigned_to')
    end;

    select o.assigned_to, o.assignment_version
      into v_current_assigned_to, v_current_assignment_version
      from public.opportunities o
     where o.id = v_opportunity_id
       and o.company_id = p_company_id;

    v_current_found := found;

    if not v_current_found
      or v_current_assigned_to is distinct from v_expected_assigned_to
      or v_current_assignment_version is distinct from v_expected_assignment_version
    then
      raise exception using
        errcode = '40001',
        message = 'assignment_resolution_conflict',
        detail = jsonb_build_object(
          'opportunity_id', v_opportunity_id,
          'assigned_to', v_current_assigned_to,
          'assignment_version', v_current_assignment_version
        )::text;
    end if;

    if v_new_assigned_to is not null
      and not private.user_is_guarded_assignment_target_eligible(
        v_new_assigned_to,
        p_company_id
      )
    then
      raise exception 'assignment_target_ineligible'
        using errcode = '22023';
    end if;

    v_result := public.change_opportunity_assignment_as_system(
      p_opportunity_id => v_opportunity_id,
      p_expected_assignment_version => v_expected_assignment_version,
      p_expected_assigned_to => v_expected_assigned_to,
      p_new_assigned_to => v_new_assigned_to,
      p_system_source => 'permission_change',
      p_actor_user_id => p_actor_user_id,
      p_suggestion_id => null,
      p_metadata => jsonb_build_object(
        'mutation_kind', p_mutation_kind,
        'subject_id', p_subject_id,
        'disposition', case
          when v_new_assigned_to is null then 'unassign'
          else 'transfer'
        end
      )
    );

    if coalesce((v_result ->> 'conflict')::boolean, false) then
      raise exception using
        errcode = '40001',
        message = 'assignment_resolution_conflict',
        detail = jsonb_build_object(
          'opportunity_id', v_opportunity_id,
          'assigned_to', v_result -> 'assigned_to',
          'assignment_version', v_result -> 'assignment_version'
        )::text;
    end if;

    v_applied := v_applied + 1;
  end loop;

  if exists (
    select 1
      from private.stranded_permission_assignments(
        p_company_id,
        p_affected_user_ids
      )
  ) then
    raise exception 'assignment_resolution_incomplete'
      using errcode = '23514';
  end if;

  return v_applied;
end;
$_$;


ALTER FUNCTION private.enforce_permission_assignment_resolutions(p_actor_user_id uuid, p_company_id uuid, p_affected_user_ids uuid[], p_assignment_resolutions jsonb, p_mutation_kind text, p_subject_id uuid) OWNER TO postgres;

--
-- Name: enqueue_email_assignment_contact_form_draft(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enqueue_email_assignment_contact_form_draft(p_assignment_event_id uuid, p_source_activity_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  event public.opportunity_assignment_events%rowtype;
  opportunity public.opportunities%rowtype;
  activity public.activities%rowtype;
  connection public.email_connections%rowtype;
  client public.clients%rowtype;
  user_row public.users%rowtype;
  v_match text[];
  v_connection_id uuid;
  v_provider_message_id text;
  v_actor_user_id uuid;
  v_customer_email text;
  v_customer_name text;
begin
  select assignment_event.* into event
  from public.opportunity_assignment_events assignment_event
  where assignment_event.id = p_assignment_event_id;
  if not found or event.new_assignee_id is null then
    return;
  end if;

  -- Permanent event provenance protects both initial and later activity rendezvous.
  if event.source = 'agent_customer_update' then return; end if;

  v_actor_user_id := event.new_assignee_id;

  select opportunity_row.* into opportunity
  from public.opportunities opportunity_row
  where opportunity_row.id = event.opportunity_id
    and opportunity_row.company_id = event.company_id
    and opportunity_row.assigned_to = event.new_assignee_id
    and opportunity_row.assignment_version = event.assignment_version
    and opportunity_row.deleted_at is null
    and opportunity_row.archived_at is null
    and opportunity_row.stage not in ('won', 'lost', 'discarded')
    and opportunity_row.source::text = 'email';
  if not found then
    return;
  end if;

  -- A verified current event may invalidate older work. The event/version
  -- equality above prevents delayed future rendezvous from staling the current
  -- assignment.
  update public.email_assignment_contact_form_draft_queue queue
     set status = case
           when queue.provider_create_started_at is not null then
             'reconciliation_required'
           else 'stale'
         end,
         lease_holder = null,
         lease_expires_at = null,
         completed_at = case
           when queue.provider_create_started_at is not null then now()
           else null
         end,
         result_reason = case
           when queue.provider_create_started_at is not null then
             'provider_reconciliation_required'
           else null
         end,
         last_error = 'assignment superseded',
         updated_at = now()
   where queue.opportunity_id = event.opportunity_id
     and queue.assignment_version <> event.assignment_version
     and queue.status in ('pending', 'processing', 'retrying');

  if opportunity.source_thread_key is null
     or opportunity.source_thread_key !~
       '^email:[^:]+:[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89ab][0-9a-fA-F]{3}-[0-9a-fA-F]{12}:message:.+$'
  then
    return;
  end if;
  v_match := regexp_match(
    opportunity.source_thread_key,
    '^email:([^:]+):([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89ab][0-9a-fA-F]{3}-[0-9a-fA-F]{12}):message:(.+)$'
  );
  if v_match is null or array_length(v_match, 1) <> 3 then
    return;
  end if;
  v_connection_id := v_match[2]::uuid;
  v_provider_message_id := btrim(v_match[3]);

  select connection_row.* into connection
  from public.email_connections connection_row
  where connection_row.id = v_connection_id
    and connection_row.company_id = opportunity.company_id::text
    and lower(connection_row.provider::text) = lower(v_match[1])
    and connection_row.status = 'active'
    and coalesce(connection_row.sync_enabled, false)
    and connection_row.type::text in ('company', 'individual');
  if not found then
    return;
  end if;

  select user_record.* into user_row
  from public.users user_record
  where user_record.id = v_actor_user_id
    and user_record.company_id = opportunity.company_id
    and user_record.deleted_at is null
    and coalesce(user_record.is_active, false);
  if not found then
    return;
  end if;

  if connection.type::text = 'individual'
     and connection.user_id is distinct from v_actor_user_id::text then
    return;
  elsif connection.type::text <> 'company'
     and connection.type::text <> 'individual' then
    return;
  end if;

  select activity_row.* into activity
  from public.activities activity_row
  where (p_source_activity_id is null or activity_row.id = p_source_activity_id)
    and activity_row.company_id = opportunity.company_id
    and activity_row.opportunity_id = opportunity.id
    and activity_row.email_connection_id = v_connection_id
    and activity_row.email_message_id = v_provider_message_id
    and activity_row.type = 'email'
    and activity_row.direction = 'inbound'
    and not coalesce(activity_row.match_needs_review, false)
    and nullif(btrim(coalesce(activity_row.email_thread_id, '')), '') is not null
    and nullif(btrim(coalesce(activity_row.from_email, '')), '') is not null
    and nullif(btrim(coalesce(activity_row.body_text, '')), '') is not null
  order by activity_row.created_at asc, activity_row.id asc
  limit 1;
  if not found then
    return;
  end if;

  select client_row.* into client
  from public.clients client_row
  where client_row.id = coalesce(opportunity.client_ref, opportunity.client_id)
    and client_row.company_id = opportunity.company_id
    and client_row.deleted_at is null;

  v_customer_email :=
    private.email_assignment_contact_form_draft_canonical_recipient(
      opportunity.company_id,
      opportunity.id,
      activity.id,
      connection.id,
      v_provider_message_id,
      btrim(activity.email_thread_id)
    );
  if v_customer_email is null then
    return;
  end if;

  v_customer_name := coalesce(
    nullif(btrim(opportunity.contact_name), ''),
    nullif(btrim(client.name), '')
  );
  if private.email_assignment_contact_form_draft_has_reply(
    opportunity.company_id,
    opportunity.id,
    connection.id,
    activity.created_at,
    v_customer_email
  ) then
    return;
  end if;

  -- Provenance gate. The message-scoped source key
  -- (`email:<provider>:<connection>:message:<id>`) is byte-identical for a
  -- contact-form notification and for a trusted generic forward, so the key
  -- cannot tell them apart and an ordinary forward was reaching the auto-draft
  -- worker, whose parser then failed deterministically eight times before the
  -- row went terminal. Mirror the parser's STRUCTURAL acceptance markers here
  -- and refuse to enqueue a source that carries none of them and has no
  -- service attestation: that mail takes the ordinary assignment-notification
  -- lane instead of a first-reply draft.
  --
  -- Deliberately coarser than the TypeScript parser (marker presence, not a
  -- full parse). The worker's parser stays authoritative at draft time; this
  -- gate only has to exclude wrapper-less ordinary mail.
  if not coalesce(
       private.email_contact_form_source_markers_present(
         coalesce(activity.subject, ''),
         coalesce(activity.body_text, '')
       ),
       false
     )
     and not exists (
       select 1
       from private.email_contact_form_recipient_attestations attestation
       where attestation.source_activity_id = activity.id
         and attestation.company_id = opportunity.company_id
         and attestation.opportunity_id = opportunity.id
         and attestation.connection_id = connection.id
         and attestation.provider_message_id = v_provider_message_id
         and attestation.provider_thread_id = btrim(activity.email_thread_id)
     ) then
    return;
  end if;

  insert into public.email_assignment_contact_form_draft_queue (
    assignment_event_id,
    company_id,
    opportunity_id,
    assignment_version,
    actor_user_id,
    connection_id,
    source_activity_id,
    provider_message_id,
    source_provider_thread_id,
    customer_email,
    customer_name,
    source_subject,
    source_body_text
  ) values (
    event.id,
    opportunity.company_id,
    opportunity.id,
    event.assignment_version,
    v_actor_user_id,
    connection.id,
    activity.id,
    v_provider_message_id,
    btrim(activity.email_thread_id),
    v_customer_email,
    v_customer_name,
    coalesce(activity.subject, ''),
    activity.body_text
  )
  on conflict (assignment_event_id) do nothing;
end;
$_$;


ALTER FUNCTION private.enqueue_email_assignment_contact_form_draft(p_assignment_event_id uuid, p_source_activity_id uuid) OWNER TO postgres;

--
-- Name: enqueue_user_override_change(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enqueue_user_override_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
begin
  if tg_op <> 'INSERT' then
    perform private.enqueue_user_permission_change(
      old.user_id,
      old.company_id,
      'user_override'
    );
  end if;
  if tg_op <> 'DELETE' then
    perform private.enqueue_user_permission_change(
      new.user_id,
      new.company_id,
      'user_override'
    );
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.enqueue_user_override_change() OWNER TO postgres;

--
-- Name: enqueue_user_permission_change(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.enqueue_user_permission_change(p_user_id uuid, p_company_id uuid, p_change_kind text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
begin
  if p_user_id is null
    or p_company_id is null
    or p_change_kind not in (
      'role_permission',
      'user_role',
      'user_override',
      'user_authority',
      'company_authority'
    )
    or not exists (
      select 1
        from public.users u
       where u.id = p_user_id
    )
    or not exists (
      select 1
        from public.companies c
       where c.id = p_company_id
    )
  then
    return;
  end if;

  insert into public.user_permission_change_deliveries (
    transaction_id,
    company_id,
    recipient_user_id,
    change_kind
  ) values (
    txid_current(),
    p_company_id,
    p_user_id,
    p_change_kind
  )
  on conflict (transaction_id, recipient_user_id) do update
    set company_id = excluded.company_id,
        change_kind = case
          when user_permission_change_deliveries.change_kind = excluded.change_kind
            then excluded.change_kind
          else 'multiple'
        end,
        changed_at = clock_timestamp();
end;
$$;


ALTER FUNCTION private.enqueue_user_permission_change(p_user_id uuid, p_company_id uuid, p_change_kind text) OWNER TO postgres;

--
-- Name: get_current_user_id(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.get_current_user_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT id FROM public.users
  WHERE (auth_id = (auth.jwt() ->> 'sub') OR firebase_uid = (auth.jwt() ->> 'sub'))
    AND deleted_at IS NULL
  LIMIT 1
$$;


ALTER FUNCTION private.get_current_user_id() OWNER TO postgres;

--
-- Name: get_user_company_id(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.get_user_company_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT company_id FROM public.users
  WHERE (auth_id = (auth.jwt() ->> 'sub') OR firebase_uid = (auth.jwt() ->> 'sub'))
    AND company_id IS NOT NULL
    AND deleted_at IS NULL
  LIMIT 1
$$;


ALTER FUNCTION private.get_user_company_id() OWNER TO postgres;

--
-- Name: guard_opportunity_assignment_mutation(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_opportunity_assignment_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
declare
  v_token_consumed boolean;
begin
  if tg_op = 'INSERT' then
    if new.assigned_to is null and new.assignment_version = 0 then
      return new;
    end if;

    if new.assigned_to is null or new.assignment_version <> 1 then
      raise exception 'assignment_write_forbidden'
        using errcode = '42501';
    end if;

    delete from private.opportunity_assignment_write_tokens t
     where t.transaction_id = txid_current()
       and t.backend_pid = pg_backend_pid()
       and t.opportunity_id = new.id
       and t.operation = 'insert'
       and t.assigned_to is not distinct from new.assigned_to
       and t.assignment_version = new.assignment_version
    returning true into v_token_consumed;

    if not found or not coalesce(v_token_consumed, false) then
      raise exception 'assignment_write_forbidden'
        using errcode = '42501';
    end if;

    return new;
  end if;

  if new.assigned_to is not distinct from old.assigned_to then
    if new.assignment_version is distinct from old.assignment_version then
      raise exception 'assignment_write_forbidden'
        using errcode = '42501';
    end if;
    return new;
  end if;

  if new.assignment_version <> old.assignment_version + 1 then
    raise exception 'assignment_write_forbidden'
      using errcode = '42501';
  end if;

  delete from private.opportunity_assignment_write_tokens t
   where t.transaction_id = txid_current()
     and t.backend_pid = pg_backend_pid()
     and t.opportunity_id = new.id
     and t.operation = 'update'
     and t.assigned_to is not distinct from new.assigned_to
     and t.assignment_version = new.assignment_version
  returning true into v_token_consumed;

  if not found or not coalesce(v_token_consumed, false) then
    raise exception 'assignment_write_forbidden'
      using errcode = '42501';
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.guard_opportunity_assignment_mutation() OWNER TO postgres;

--
-- Name: guard_user_overrides_final_state(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_user_overrides_final_state() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
declare
  v_user_id uuid;
  v_user_ids uuid[] := array_remove(array[
    case when tg_op in ('UPDATE', 'DELETE') then old.user_id else null end,
    case when tg_op in ('INSERT', 'UPDATE') then new.user_id else null end
  ], null);
begin
  if tg_op in ('UPDATE', 'DELETE')
    and old.permission = 'spec.admin'
  then
    raise exception 'direct_permission_write_invalid: protected_permission_override'
      using errcode = '23514';
  end if;

  if tg_op in ('INSERT', 'UPDATE')
    and new.permission = 'spec.admin'
  then
    raise exception 'direct_permission_write_invalid: protected_permission_override'
      using errcode = '23514';
  end if;

  foreach v_user_id in array v_user_ids
  loop
    if exists (
      select 1
        from public.users u
       where u.id = v_user_id
         and private.permission_user_is_admin(u.id, u.company_id)
    ) then
      raise exception 'target_is_admin'
        using errcode = '42501';
    end if;
    perform private.assert_direct_permission_user(v_user_id);
  end loop;
  return null;
end;
$$;


ALTER FUNCTION private.guard_user_overrides_final_state() OWNER TO postgres;

--
-- Name: is_canonical_internal_permission_override(text, uuid, text, boolean); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.is_canonical_internal_permission_override(p_permission text, p_company_id uuid, p_scope text, p_granted boolean) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select coalesce(
    p_permission = 'spec.admin'
    and p_company_id = '00000000-0000-0000-0000-00000000000a'::uuid
    and p_scope = 'all'
    and p_granted is true,
    false
  );
$$;


ALTER FUNCTION private.is_canonical_internal_permission_override(p_permission text, p_company_id uuid, p_scope text, p_granted boolean) OWNER TO postgres;

--
-- Name: least_permissive_pipeline_scope(text, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.least_permissive_pipeline_scope(p_left_scope text, p_right_scope text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select case
    when p_left_scope is null or p_right_scope is null then null
    when p_left_scope not in ('all', 'assigned') then null
    when p_right_scope not in ('all', 'assigned') then null
    when p_left_scope = 'assigned' or p_right_scope = 'assigned' then 'assigned'
    else 'all'
  end;
$$;


ALTER FUNCTION private.least_permissive_pipeline_scope(p_left_scope text, p_right_scope text) OWNER TO postgres;

--
-- Name: lock_lead_assignment_company(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.lock_lead_assignment_company(p_company_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
begin
  if p_company_id is null then
    raise exception 'lead_assignment_company_lock_required'
      using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'lead-assignment-company:' || p_company_id::text,
      161000
    )
  );
end;
$$;


ALTER FUNCTION private.lock_lead_assignment_company(p_company_id uuid) OWNER TO postgres;

