-- Name: normalize_address(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.normalize_address(p text) RETURNS text
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'private'
    AS $$
  select private.normalize_property_address(p, true);
$$;


ALTER FUNCTION private.normalize_address(p text) OWNER TO postgres;

--
-- Name: normalize_property_address(text, boolean); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.normalize_property_address(p_address text, p_include_unit boolean DEFAULT true) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'private'
    AS $_$
declare
  v_raw text := btrim(coalesce(p_address, ''));
  v_property text;
  v_canonical text;
  v_base text;
  v_unit text;
  v_tokens text[];
  v_index integer;
  v_token text;
begin
  if v_raw = ''
    or v_raw ~* '^\s*(p\.?\s*o\.?\s+box|post office box)\y'
  then
    return '';
  end if;

  if v_raw ~* '^\s*(apartment|suite|unit|ste|apt|#)\s*\.?\s*#?\s*[a-z0-9]+([-/][a-z0-9]+)*\s*[,;:-]?\s*.+$'
  then
    v_unit := lower(
      substring(
        lower(v_raw) from '^\s*(?:apartment|suite|unit|ste|apt|#)\s*\.?\s*#?\s*([a-z0-9]+(?:[-/][a-z0-9]+)*)'
      )
    );
    v_property := regexp_replace(
      v_raw,
      '^\s*(apartment|suite|unit|ste|apt|#)\s*\.?\s*#?\s*[a-z0-9]+([-/][a-z0-9]+)*\s*[,;:-]?\s*',
      '',
      'i'
    );
  elsif v_raw ~* '^\s*[a-z0-9]+\s*-\s*[0-9]+[a-z]?\s+.+$'
  then
    v_unit := lower(
      substring(lower(v_raw) from '^\s*([a-z0-9]+)\s*-\s*[0-9]+[a-z]?\s+')
    );
    v_property := regexp_replace(
      v_raw,
      '^\s*[a-z0-9]+\s*-\s*([0-9]+[a-z]?)\s+(.+)$',
      '\1 \2',
      'i'
    );
  elsif v_raw ~* '(^|[,\s]+)(apartment|suite|unit|ste|apt|#)\s*\.?\s*#?\s*[a-z0-9]+([-/][a-z0-9]+)*\y'
  then
    v_unit := lower(
      substring(
        lower(v_raw) from '(?:^|[,\s]+)(?:apartment|suite|unit|ste|apt|#)\s*\.?\s*#?\s*([a-z0-9]+(?:[-/][a-z0-9]+)*)'
      )
    );
    v_property := regexp_replace(
      v_raw,
      '(^|[,\s]+)(apartment|suite|unit|ste|apt|#)\s*\.?\s*#?\s*[a-z0-9]+([-/][a-z0-9]+)*.*$',
      '',
      'i'
    );
  else
    v_property := v_raw;
  end if;

  v_canonical := private.canonicalize_address_text(v_property);
  if length(v_canonical) < 5 then
    return '';
  end if;

  if v_canonical ~ '^[0-9]{1,6}[a-z]?\s+(?=\S*[a-z])\S+' then
    v_tokens := regexp_split_to_array(v_canonical, '\s+');
    v_base := null;

    if v_tokens[2] = 'highway'
      and coalesce(v_tokens[3], '') ~ '^[a-z0-9-]+$'
    then
      v_base := array_to_string(v_tokens[1:3], ' ');
    elsif v_tokens[2] in ('range', 'township')
      and v_tokens[3] = 'road'
      and coalesce(v_tokens[4], '') ~ '^[a-z0-9-]+$'
    then
      v_base := array_to_string(v_tokens[1:4], ' ');
    else
      for v_index in 3..coalesce(array_length(v_tokens, 1), 0) loop
        v_token := v_tokens[v_index];
        if v_token in (
          'avenue', 'boulevard', 'circle', 'court', 'crescent', 'drive',
          'highway', 'lane', 'parkway', 'place', 'road', 'square', 'street',
          'terrace', 'trail', 'way'
        ) then
          v_base := array_to_string(v_tokens[1:v_index], ' ');
          exit;
        end if;
      end loop;
    end if;
    if v_base is null then
      return '';
    end if;
  elsif v_canonical ~ '^(rr|rural route)\s*[0-9]+\y.*\y(site|box|lot)\s*[a-z0-9-]+\y'
    or v_canonical ~ '^(site|box)\s*[a-z0-9-]+\y.*\y(rr|rural route)\s*[0-9]+\y'
    or v_canonical ~ '^lot\s+[a-z0-9-]+\y.*\y(concession|block|plan)\s+[a-z0-9-]+\y'
  then
    v_base := v_canonical;
  elsif v_canonical ~ '^(parcel|pid)\s+[a-z0-9][a-z0-9-]{4,}\y'
  then
    v_base := v_canonical;
  else
    return '';
  end if;

  if p_include_unit and nullif(v_unit, '') is not null then
    return v_base || ' unit ' || v_unit;
  end if;
  return v_base;
end;
$_$;


ALTER FUNCTION private.normalize_property_address(p_address text, p_include_unit boolean) OWNER TO postgres;

--
-- Name: notify_email_assignment_contact_form_draft_reconciliation(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.notify_email_assignment_contact_form_draft_reconciliation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_connection public.email_connections%rowtype;
  v_recipient_user_id uuid;
  v_dedupe_key text;
  v_action_url text;
  v_action_label text;
begin
  if new.status <> 'reconciliation_required'
     or old.status = 'reconciliation_required' then
    return new;
  end if;

  select connection.* into v_connection
  from public.email_connections connection
  where connection.id = new.connection_id
    and connection.company_id = new.company_id::text;
  if not found then
    return new;
  end if;

  if v_connection.type::text = 'individual' then
    select user_row.id into v_recipient_user_id
    from public.users user_row
    where user_row.id::text = v_connection.user_id
      and user_row.company_id = new.company_id
      and user_row.deleted_at is null
      and coalesce(user_row.is_active, false)
    order by user_row.id
    limit 1;
    -- The personal-mailbox owner is the only safe reconciliation authority,
    -- but the OPS settings surface can be permission-gated. The notice itself
    -- therefore tells the owner to inspect their provider Drafts folder without
    -- linking them to a route they may not be authorized to open.
    v_action_url := null;
    v_action_label := null;
  elsif v_connection.type::text = 'company' then
    v_action_url := '/settings?tab=integrations';
    v_action_label := 'Review mailbox';
    for v_recipient_user_id in
      select user_row.id
      from public.users user_row
      where user_row.company_id = new.company_id
        and user_row.deleted_at is null
        and coalesce(user_row.is_active, false)
        and public.has_permission(
          user_row.id,
          'settings.integrations',
          'all'
        )
      order by user_row.id
    loop
      v_dedupe_key :=
        'email-assignment-draft-reconciliation:' || new.id::text;
      if not exists (
        select 1
        from public.notifications notification
        where notification.user_id = v_recipient_user_id::text
          and notification.company_id = new.company_id::text
          and notification.type = 'system'
          and notification.dedupe_key = v_dedupe_key
      ) then
        insert into public.notifications (
          user_id,
          company_id,
          type,
          title,
          body,
          is_read,
          persistent,
          action_url,
          action_label,
          dedupe_key
        ) values (
          v_recipient_user_id::text,
          new.company_id::text,
          'system',
          'Draft placement needs review',
          'OPS could not confirm one mailbox draft. Check Drafts before creating another.',
          false,
          true,
          v_action_url,
          v_action_label,
          v_dedupe_key
        )
        on conflict do nothing;
      end if;
    end loop;
    return new;
  end if;

  if v_recipient_user_id is null then
    return new;
  end if;

  v_dedupe_key :=
    'email-assignment-draft-reconciliation:' || new.id::text;
  if exists (
    select 1
    from public.notifications notification
    where notification.user_id = v_recipient_user_id::text
      and notification.company_id = new.company_id::text
      and notification.type = 'system'
      and notification.dedupe_key = v_dedupe_key
  ) then
    return new;
  end if;

  insert into public.notifications (
    user_id,
    company_id,
    type,
    title,
    body,
    is_read,
    persistent,
    action_url,
    action_label,
    dedupe_key
  ) values (
    v_recipient_user_id::text,
    new.company_id::text,
    'system',
    'Draft placement needs review',
    'OPS could not confirm one mailbox draft. Check Drafts before creating another.',
    false,
    true,
    v_action_url,
    v_action_label,
    v_dedupe_key
  )
  on conflict do nothing;

  return new;
end;
$$;


ALTER FUNCTION private.notify_email_assignment_contact_form_draft_reconciliation() OWNER TO postgres;

--
-- Name: permission_scope_rank(text); Type: FUNCTION; Schema: private; Owner: postgres
