CREATE FUNCTION private.permission_scope_rank(p_scope text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select case p_scope
    when 'all' then 2
    when 'assigned' then 1
    else 0
  end;
$$;


