--
-- Name: permission_user_is_admin(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.permission_user_is_admin(p_user_id uuid, p_company_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
  select exists (
    select 1
      from public.users u
      left join public.companies c on c.id = u.company_id
     where u.id = p_user_id
       and u.company_id = p_company_id
       and u.deleted_at is null
       and coalesce(u.is_active, false)
       and (
         coalesce(u.is_company_admin, false)
         or u.id::text = c.account_holder_id
         or u.id::text = any(coalesce(c.admin_ids, array[]::text[]))
       )
  );
$$;


ALTER FUNCTION private.permission_user_is_admin(p_user_id uuid, p_company_id uuid) OWNER TO postgres;

--
-- Name: pipeline_dependency_issues(text, text, text, text, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.pipeline_dependency_issues(p_create_scope text, p_view_scope text, p_edit_scope text, p_assign_scope text, p_convert_scope text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_issues jsonb := '[]'::jsonb;
begin
  if p_create_scope is not null and p_create_scope <> 'all' then
    v_issues := v_issues || jsonb_build_array(jsonb_build_object(
      'code', 'unsupported_scope',
      'permission', 'pipeline.create',
      'scope', p_create_scope
    ));
  end if;

  if p_view_scope is not null and p_view_scope not in ('all', 'assigned') then
    v_issues := v_issues || jsonb_build_array(jsonb_build_object(
      'code', 'unsupported_scope',
      'permission', 'pipeline.view',
      'scope', p_view_scope
    ));
  end if;

  if p_edit_scope is not null and p_edit_scope not in ('all', 'assigned') then
    v_issues := v_issues || jsonb_build_array(jsonb_build_object(
      'code', 'unsupported_scope',
      'permission', 'pipeline.edit',
      'scope', p_edit_scope
    ));
  end if;

  if p_assign_scope is not null and p_assign_scope not in ('all', 'assigned') then
    v_issues := v_issues || jsonb_build_array(jsonb_build_object(
      'code', 'unsupported_scope',
      'permission', 'pipeline.assign',
      'scope', p_assign_scope
    ));
  end if;

  if p_convert_scope is not null and p_convert_scope not in ('all', 'assigned') then
    v_issues := v_issues || jsonb_build_array(jsonb_build_object(
      'code', 'unsupported_scope',
      'permission', 'pipeline.convert',
      'scope', p_convert_scope
    ));
  end if;

  if p_create_scope is not null
    and private.permission_scope_rank(p_view_scope) < 1
  then
    v_issues := v_issues || jsonb_build_array(jsonb_build_object(
      'code', 'create_requires_view',
      'permission', 'pipeline.create',
      'dependency', 'pipeline.view'
    ));
  end if;

  if p_edit_scope is not null
    and private.permission_scope_rank(p_edit_scope)
      > private.permission_scope_rank(p_view_scope)
  then
    v_issues := v_issues || jsonb_build_array(jsonb_build_object(
      'code', 'edit_exceeds_view',
      'permission', 'pipeline.edit',
      'dependency', 'pipeline.view'
    ));
  end if;

  if p_assign_scope is not null
    and private.permission_scope_rank(p_assign_scope)
      > private.permission_scope_rank(p_edit_scope)
  then
    v_issues := v_issues || jsonb_build_array(jsonb_build_object(
      'code', 'assign_exceeds_edit',
      'permission', 'pipeline.assign',
      'dependency', 'pipeline.edit'
    ));
  end if;

  if p_convert_scope is not null
    and private.permission_scope_rank(p_convert_scope)
      > private.permission_scope_rank(p_edit_scope)
  then
    v_issues := v_issues || jsonb_build_array(jsonb_build_object(
      'code', 'convert_exceeds_edit',
      'permission', 'pipeline.convert',
      'dependency', 'pipeline.edit'
    ));
  end if;

  return v_issues;
end;
$$;


ALTER FUNCTION private.pipeline_dependency_issues(p_create_scope text, p_view_scope text, p_edit_scope text, p_assign_scope text, p_convert_scope text) OWNER TO postgres;

--
-- Name: pipeline_dependency_issues_for_user(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.pipeline_dependency_issues_for_user(p_user_id uuid, p_company_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
  select private.pipeline_dependency_issues(
    private.raw_pipeline_scope_for_user(p_user_id, p_company_id, 'pipeline.create'),
    private.raw_pipeline_scope_for_user(p_user_id, p_company_id, 'pipeline.view'),
    private.raw_pipeline_scope_for_user(p_user_id, p_company_id, 'pipeline.edit'),
    private.raw_pipeline_scope_for_user(p_user_id, p_company_id, 'pipeline.assign'),
    private.raw_pipeline_scope_for_user(p_user_id, p_company_id, 'pipeline.convert')
  );
$$;


ALTER FUNCTION private.pipeline_dependency_issues_for_user(p_user_id uuid, p_company_id uuid) OWNER TO postgres;

--
-- Name: preserve_exact_recovery_opportunity_updated_at(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.preserve_exact_recovery_opportunity_updated_at() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
declare
  v_consumed boolean;
begin
  if old.id is distinct from new.id
    or old.company_id is distinct from new.company_id
    or to_jsonb(new) - array[
      'correspondence_count',
      'inbound_count',
      'outbound_count',
      'last_inbound_at',
      'last_outbound_at',
      'last_message_direction',
      'last_activity_at',
      'updated_at'
    ] is distinct from to_jsonb(old) - array[
      'correspondence_count',
      'inbound_count',
      'outbound_count',
      'last_inbound_at',
      'last_outbound_at',
      'last_message_direction',
      'last_activity_at',
      'updated_at'
    ]
  then
    return new;
  end if;

  delete from private.exact_recovery_opportunity_timestamp_tokens token
  where token.transaction_id = pg_catalog.txid_current()
    and token.backend_pid = pg_catalog.pg_backend_pid()
    and token.company_id = old.company_id
    and token.opportunity_id = old.id
    and token.expected_updated_at is not distinct from old.updated_at
  returning true into v_consumed;

  if found and coalesce(v_consumed, false) then
    new.updated_at := old.updated_at;
  end if;
  return new;
end;
$$;


ALTER FUNCTION private.preserve_exact_recovery_opportunity_updated_at() OWNER TO postgres;

