--
-- Name: raw_permission_scope_for_user(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.raw_permission_scope_for_user(p_actor_user_id uuid, p_actor_company_id uuid, p_permission text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
declare
  v_override_granted boolean;
  v_override_scope text;
  v_scope text;
begin
  if p_actor_user_id is null
     or p_actor_company_id is null
     or nullif(btrim(p_permission), '') is null then
    return null;
  end if;

  if not exists (
    select 1
    from public.users actor
    join public.companies company
      on company.id = actor.company_id
     and company.deleted_at is null
    where actor.id = p_actor_user_id
      and actor.company_id = p_actor_company_id
      and actor.deleted_at is null
      and coalesce(actor.is_active, false)
  ) then
    return null;
  end if;

  select override.granted, override.scope
  into v_override_granted, v_override_scope
  from public.user_permission_overrides override
  where override.user_id = p_actor_user_id
    and override.company_id = p_actor_company_id
    and override.permission = p_permission
  limit 1;

  if found then
    if not v_override_granted then
      return null;
    end if;
    if v_override_scope is not null then
      if v_override_scope in ('all', 'assigned', 'own') then
        return v_override_scope;
      end if;
      return null;
    end if;
  end if;

  select permission.scope
  into v_scope
  from public.user_roles assignment
  join public.roles role
    on role.id = assignment.role_id
   and (role.is_preset or role.company_id = p_actor_company_id)
  join public.role_permissions permission
    on permission.role_id = assignment.role_id
   and permission.permission = p_permission
   and permission.scope in ('all', 'assigned', 'own')
  where assignment.user_id = p_actor_user_id::text
  order by case permission.scope
    when 'all' then 1
    when 'assigned' then 2
    when 'own' then 3
    else 4
  end
  limit 1;

  return v_scope;
end;
$$;


ALTER FUNCTION private.raw_permission_scope_for_user(p_actor_user_id uuid, p_actor_company_id uuid, p_permission text) OWNER TO postgres;

--
-- Name: raw_pipeline_scope_for_user(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.raw_pipeline_scope_for_user(p_user_id uuid, p_company_id uuid, p_permission text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
declare
  v_override_found boolean := false;
  v_override_granted boolean;
  v_override_scope text;
  v_role_scope text;
begin
  if p_permission not in (
    'pipeline.create',
    'pipeline.view',
    'pipeline.edit',
    'pipeline.assign',
    'pipeline.convert'
  )
    or not exists (
      select 1
        from public.users u
       where u.id = p_user_id
         and u.company_id = p_company_id
         and u.deleted_at is null
         and coalesce(u.is_active, false)
    )
  then
    return null;
  end if;

  if private.permission_user_is_admin(p_user_id, p_company_id) then
    return 'all';
  end if;

  select upo.granted, upo.scope, true
    into v_override_granted, v_override_scope, v_override_found
    from public.user_permission_overrides upo
   where upo.user_id = p_user_id
     and upo.company_id = p_company_id
     and upo.permission = p_permission
   limit 1;

  if v_override_found then
    if not v_override_granted then
      return null;
    end if;
    if v_override_scope is not null then
      return v_override_scope;
    end if;
  end if;

  select rp.scope
    into v_role_scope
    from public.user_roles ur
    join public.role_permissions rp on rp.role_id = ur.role_id
   where ur.user_id = p_user_id::text
     and rp.permission = p_permission
   limit 1;

  if found then
    return v_role_scope;
  end if;

  if private.should_use_pipeline_manage_compat(
    p_user_id,
    p_company_id,
    p_permission
  ) then
    return 'all';
  end if;

  return null;
end;
$$;


ALTER FUNCTION private.raw_pipeline_scope_for_user(p_user_id uuid, p_company_id uuid, p_permission text) OWNER TO postgres;

--
-- Name: resolve_email_assignment_contact_form_draft_mailbox_wait_notifi(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.resolve_email_assignment_contact_form_draft_mailbox_wait_notifi() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.mailbox_busy_since is null then
    return new;
  end if;

  if new.mailbox_busy_since is not null
     and new.status in ('pending', 'processing', 'retrying') then
    return new;
  end if;

  update public.notifications notification
     set is_read = true,
         resolved_at = clock_timestamp(),
         resolution_reason = 'mailbox_draft_wait_cleared',
         resolved_by = null
   where notification.company_id = new.company_id::text
     and notification.type = 'system'
     and notification.dedupe_key =
       'email-assignment-draft-mailbox-wait:' || new.id::text
     and notification.resolved_at is null;

  return new;
end;
$$;


ALTER FUNCTION private.resolve_email_assignment_contact_form_draft_mailbox_wait_notifi() OWNER TO postgres;

--
-- Name: resolve_unassigned_lead_assignment_deliveries(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.resolve_unassigned_lead_assignment_deliveries() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
begin
  if new.new_assignee_id is null then
    return new;
  end if;

  update public.notifications notification
  set is_read = true,
      resolved_at = now(),
      resolution_reason = 'lead_assignment_completed'
  where exists (
    select 1
    from public.unassigned_lead_assignment_deliveries delivery
    where delivery.company_id = new.company_id
      and delivery.opportunity_id = new.opportunity_id
      and delivery.notification_id = notification.id
      and notification.dedupe_key =
        'unassigned-lead-assignment-delivery:' || delivery.id::text
  )
    and notification.resolved_at is null;

  update public.unassigned_lead_assignment_deliveries delivery
  set state = 'delivered',
      claimed_at = null,
      claimed_by = null,
      lease_token = null,
      lease_expires_at = null,
      disposition = 'assigned',
      push_state = case
        when delivery.push_state = 'sent' then 'sent'
        else 'suppressed'
      end,
      delivered_at = coalesce(delivery.delivered_at, now()),
      terminal_at = null,
      last_error = null,
      updated_at = now()
  where delivery.company_id = new.company_id
    and delivery.opportunity_id = new.opportunity_id
    and delivery.disposition is distinct from 'assigned';

  return new;
end;
$$;


ALTER FUNCTION private.resolve_unassigned_lead_assignment_deliveries() OWNER TO postgres;

--
-- Name: rotate_site_visit_stage_revision(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.rotate_site_visit_stage_revision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- AFTER row trigger sees the final values produced by existing BEFORE
  -- triggers. No company/advisory/visit locks here: the writer owns the parent
  -- row already. Existing rows use the reserved zero token until first change.
  if tg_op = 'UPDATE' and row(
    new.stage, new.stage_entered_at, new.stage_manually_set,
    new.stage_manual_boundary_event_id, new.stage_manual_boundary_at,
    new.stage_manual_corrected_at, new.assigned_to, new.assignment_version,
    new.company_id, new.deleted_at, new.archived_at,
    new.merged_into_opportunity_id, new.project_id, new.project_ref
  ) is not distinct from row(
    old.stage, old.stage_entered_at, old.stage_manually_set,
    old.stage_manual_boundary_event_id, old.stage_manual_boundary_at,
    old.stage_manual_corrected_at, old.assigned_to, old.assignment_version,
    old.company_id, old.deleted_at, old.archived_at,
    old.merged_into_opportunity_id, old.project_id, old.project_ref
  ) then
    return new;
  end if;
  insert into private.site_visit_stage_revisions(opportunity_id, revision)
  values (new.id, gen_random_uuid())
  on conflict (opportunity_id) do update set revision = excluded.revision;
  return new;
end;
$$;


ALTER FUNCTION private.rotate_site_visit_stage_revision() OWNER TO postgres;

--
-- Name: should_use_inbox_view_company_compat(uuid, uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.should_use_inbox_view_company_compat(p_actor_user_id uuid, p_actor_company_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
  select p_actor_user_id is not null
    and p_actor_company_id is not null
    and not exists (
      select 1
        from public.user_permission_overrides upo
       where upo.user_id = p_actor_user_id
         and upo.company_id = p_actor_company_id
         and upo.permission = 'inbox.view'
    )
    and not exists (
      select 1
        from public.user_roles ur
        join public.role_permissions rp on rp.role_id = ur.role_id
       where ur.user_id = p_actor_user_id::text
         and rp.permission = 'inbox.view'
    )
    and public.has_permission(
      p_actor_user_id,
      'inbox.view_company',
      'all'
    );
$$;


