--
-- Name: stranded_permission_assignments(uuid, uuid[]); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.stranded_permission_assignments(p_company_id uuid, p_user_ids uuid[]) RETURNS TABLE(opportunity_id uuid, title text, assigned_to uuid, assignment_version bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
  select o.id, o.title, o.assigned_to, o.assignment_version
    from public.opportunities o
   where o.company_id = p_company_id
     and o.assigned_to = any(coalesce(p_user_ids, array[]::uuid[]))
     and o.deleted_at is null
     and o.archived_at is null
     and o.stage not in ('won', 'lost', 'discarded')
     and private.raw_pipeline_scope_for_user(
       o.assigned_to,
       o.company_id,
       'pipeline.view'
     ) is distinct from 'all'
     and private.raw_pipeline_scope_for_user(
       o.assigned_to,
       o.company_id,
       'pipeline.view'
     ) is distinct from 'assigned'
   order by o.id;
$$;


