--
-- Name: suppress_email_recovery_provider_draft_queue(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.suppress_email_recovery_provider_draft_queue() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_assignment_provider_mutations_disabled boolean := false;
  v_activity_provider_mutations_disabled boolean := false;
begin
  select coalesce((
    select lower(
      coalesce(assignment_event.metadata ->> 'provider_mutations_disabled', 'false')
    ) in ('true', 't', '1', 'yes')
    from public.opportunity_assignment_events assignment_event
    where assignment_event.id = new.assignment_event_id
  ), false)
  into v_assignment_provider_mutations_disabled;

  select coalesce((
    select coalesce(activity.provider_mutations_disabled, false)
    from public.activities activity
    where activity.id = new.source_activity_id
  ), false)
  into v_activity_provider_mutations_disabled;

  if v_assignment_provider_mutations_disabled
     or v_activity_provider_mutations_disabled then
    return null;
  end if;

  return new;
end;
$$;


ALTER FUNCTION private.suppress_email_recovery_provider_draft_queue() OWNER TO postgres;

--
-- Name: try_parse_uuid(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.try_parse_uuid(p_value text) RETURNS uuid
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $_$
begin
  if p_value is null then
    return null;
  end if;

  if btrim(p_value) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return btrim(p_value)::uuid;
  end if;

  return null;
end;
$_$;


ALTER FUNCTION private.try_parse_uuid(p_value text) OWNER TO postgres;

