-- Name: user_assignment_snapshot(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.user_assignment_snapshot(p_user_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  select case
    when p_user_id is null then null
    else (
      select jsonb_build_object(
        'id', u.id,
        'first_name', u.first_name,
        'last_name', u.last_name,
        'email', u.email,
        'profile_image_url', u.profile_image_url,
        'user_color', u.user_color,
        'role', u.role,
        'is_active', coalesce(u.is_active, false)
      )
      from public.users u
      where u.id = p_user_id
    )
  end;
$$;


