--
-- Name: apply_user_permission_overrides_as_system(uuid, uuid, jsonb, jsonb, text[], jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.apply_user_permission_overrides_as_system(p_actor_user_id uuid, p_target_user_id uuid, p_expected_overrides jsonb, p_set jsonb, p_clear text[], p_assignment_resolutions jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
declare
  v_actor_company_id uuid;
  v_target_company_id uuid;
  v_current_overrides jsonb;
  v_resolved_count integer;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'access_denied'
      using errcode = '42501';
  end if;

  select u.company_id
    into v_actor_company_id
    from public.users u
   where u.id = p_actor_user_id
     and u.company_id is not null
     and u.deleted_at is null
     and coalesce(u.is_active, false);
  if not found then
    raise exception 'access_denied'
      using errcode = '42501';
  end if;

  perform private.lock_lead_assignment_company(v_actor_company_id);

  perform 1
    from public.users u
   where u.id = p_actor_user_id
     and u.company_id = v_actor_company_id
     and u.deleted_at is null
     and coalesce(u.is_active, false)
     and not exists (
       select 1
         from public.user_roles ur
         join public.roles r on r.id = ur.role_id
        where ur.user_id = u.id::text
          and not (
            (r.is_preset and r.company_id is null)
            or (not r.is_preset and r.company_id = u.company_id)
          )
     )
   for share;
  if not found
    or not public.has_permission(
      p_actor_user_id,
      'team.assign_roles',
      'all'
    )
  then
    raise exception 'access_denied'
      using errcode = '42501';
  end if;

  select u.company_id
    into v_target_company_id
    from public.users u
   where u.id = p_target_user_id
     and u.company_id is not null
     and u.deleted_at is null
     and coalesce(u.is_active, false)
   for update;
  if not found then
    raise exception 'target_user_not_found'
      using errcode = 'P0002';
  end if;
  if v_target_company_id is distinct from v_actor_company_id then
    raise exception 'access_denied'
      using errcode = '42501';
  end if;
  if private.permission_user_is_admin(
    p_target_user_id,
    v_target_company_id
  ) then
    raise exception 'target_is_admin'
      using errcode = '42501';
  end if;

  perform 1
    from public.user_permission_overrides upo
   where upo.user_id = p_target_user_id
   order by upo.permission
   for update;

  if exists (
    select 1
      from public.user_permission_overrides upo
     where upo.user_id = p_target_user_id
       and upo.permission = 'spec.admin'
       and not private.is_canonical_internal_permission_override(
         upo.permission,
         upo.company_id,
         upo.scope,
         upo.granted
       )
  ) then
    raise exception 'protected_permission_override_invalid'
      using errcode = '22023';
  end if;

  if exists (
    select 1
      from public.user_permission_overrides upo
     where upo.user_id = p_target_user_id
       and upo.company_id is distinct from v_target_company_id
       and not private.is_canonical_internal_permission_override(
         upo.permission,
         upo.company_id,
         upo.scope,
         upo.granted
       )
  ) then
    raise exception 'stale_company_override'
      using errcode = '22023';
  end if;

  perform private.assert_canonical_override_payload(
    p_expected_overrides,
    false
  );
  v_current_overrides := private.canonical_user_override_snapshot(
    p_target_user_id
  );
  if v_current_overrides is distinct from p_expected_overrides then
    raise exception using
      errcode = '40001',
      message = 'permission_snapshot_mismatch',
      detail = jsonb_build_object(
        'expected_overrides', p_expected_overrides,
        'current_overrides', v_current_overrides
      )::text;
  end if;

  perform private.assert_canonical_override_payload(p_set, true);
  if p_clear is null
    or exists (select 1 from unnest(p_clear) permission where permission is null)
    or (
      select count(*) from unnest(p_clear)
    ) <> (
      select count(distinct permission) from unnest(p_clear) permission
    )
    or exists (
      select 1
        from unnest(p_clear) permission
        left join private.lead_permission_editor_registry registry
          on registry.permission = permission
       where registry.permission is null
    )
    or exists (
      select 1
        from jsonb_array_elements(p_set) entry
       where entry ->> 'permission' = any(p_clear)
    )
  then
    raise exception 'invalid_override_set_clear'
      using errcode = '22023';
  end if;

  delete from public.user_permission_overrides upo
   where upo.user_id = p_target_user_id
     and upo.permission = any(p_clear);

  insert into public.user_permission_overrides (
    user_id,
    company_id,
    permission,
    scope,
    granted
  )
  select
    p_target_user_id,
    v_target_company_id,
    entry ->> 'permission',
    case
      when jsonb_typeof(entry -> 'scope') = 'null' then null
      else entry ->> 'scope'
    end,
    (entry ->> 'granted')::boolean
  from jsonb_array_elements(p_set) entry
  on conflict (user_id, permission) do update
    set company_id = excluded.company_id,
        scope = excluded.scope,
        granted = excluded.granted,
        updated_at = now();

  perform private.assert_permission_users_valid(array[p_target_user_id]);
  v_resolved_count := private.enforce_permission_assignment_resolutions(
    p_actor_user_id,
    v_target_company_id,
    array[p_target_user_id],
    p_assignment_resolutions,
    'user_overrides',
    p_target_user_id
  );
  perform private.assert_permission_users_valid(array[p_target_user_id]);

  return jsonb_build_object(
    'ok', true,
    'user_id', p_target_user_id,
    'overrides', private.canonical_user_override_snapshot(p_target_user_id),
    'resolved_assignments', v_resolved_count
  );
end;
$$;


ALTER FUNCTION public.apply_user_permission_overrides_as_system(p_actor_user_id uuid, p_target_user_id uuid, p_expected_overrides jsonb, p_set jsonb, p_clear text[], p_assignment_resolutions jsonb) OWNER TO postgres;

--
-- Name: change_opportunity_assignment_as_system(uuid, bigint, uuid, uuid, text, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.change_opportunity_assignment_as_system(p_opportunity_id uuid, p_expected_assignment_version bigint, p_expected_assigned_to uuid, p_new_assigned_to uuid, p_system_source text, p_actor_user_id uuid DEFAULT NULL::uuid, p_suggestion_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'access_denied'
      using errcode = '42501';
  end if;

  select o.company_id
    into v_company_id
    from public.opportunities o
   where o.id = p_opportunity_id
     and o.deleted_at is null;
  if not found then
    raise exception 'opportunity_not_found'
      using errcode = 'P0002';
  end if;

  perform private.lock_lead_assignment_company(v_company_id);

  -- Freeze the company identity after taking its boundary. If a concurrent
  -- company move won before the lock, fail closed and require a fresh call.
  perform 1
    from public.opportunities o
   where o.id = p_opportunity_id
     and o.company_id = v_company_id
     and o.deleted_at is null
   for key share;
  if not found then
    raise exception 'opportunity_company_changed'
      using errcode = '40001';
  end if;

  return private.change_assignment_system_company_serialized_internal(
    p_opportunity_id => p_opportunity_id,
    p_expected_assignment_version => p_expected_assignment_version,
    p_expected_assigned_to => p_expected_assigned_to,
    p_new_assigned_to => p_new_assigned_to,
    p_system_source => p_system_source,
    p_actor_user_id => p_actor_user_id,
    p_suggestion_id => p_suggestion_id,
    p_metadata => p_metadata
  );
end;
$$;


ALTER FUNCTION public.change_opportunity_assignment_as_system(p_opportunity_id uuid, p_expected_assignment_version bigint, p_expected_assigned_to uuid, p_new_assigned_to uuid, p_system_source text, p_actor_user_id uuid, p_suggestion_id uuid, p_metadata jsonb) OWNER TO postgres;

--
-- Name: enqueue_email_signature_notification_lifecycle(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enqueue_email_signature_notification_lifecycle(p_actor_user_id uuid, p_connection_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
begin
  if p_actor_user_id is null or p_connection_id is null then
    return;
  end if;

  select actor.company_id
    into v_company_id
  from public.users actor
  join public.email_connections connection
    on connection.id = p_connection_id
   and connection.company_id = actor.company_id::text
  where actor.id = p_actor_user_id
    and actor.company_id is not null;

  if v_company_id is null then
    return;
  end if;

  perform public.enqueue_email_signature_notification_lifecycle_for_company(
    p_actor_user_id,
    p_connection_id,
    v_company_id,
    p_reason
  );
end;
$$;


ALTER FUNCTION public.enqueue_email_signature_notification_lifecycle(p_actor_user_id uuid, p_connection_id uuid, p_reason text) OWNER TO postgres;

--
-- Name: enqueue_email_signature_notification_lifecycle_for_company(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enqueue_email_signature_notification_lifecycle_for_company(p_actor_user_id uuid, p_connection_id uuid, p_company_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
begin
  if p_actor_user_id is null
     or p_connection_id is null
     or p_company_id is null
     or not exists (
       select 1
       from public.users actor
       where actor.id = p_actor_user_id
     )
     or not exists (
       select 1
       from public.companies company
       where company.id = p_company_id
     )
     or not exists (
       select 1
       from public.email_connections connection
       where connection.id = p_connection_id
     ) then
    return;
  end if;

  insert into public.email_signature_notification_lifecycle_outbox (
    actor_user_id,
    connection_id,
    company_id,
    reason,
    requested_at,
    available_at,
    processed_at,
    attempt_count,
    last_error
  ) values (
    p_actor_user_id,
    p_connection_id,
    p_company_id,
    coalesce(nullif(btrim(p_reason), ''), 'lifecycle_changed'),
    clock_timestamp(),
    clock_timestamp(),
    null,
    0,
    null
  )
  on conflict (actor_user_id, connection_id, company_id) do update
    set reason = excluded.reason,
        requested_at = excluded.requested_at,
        available_at = clock_timestamp(),
        processed_at = null,
        attempt_count = 0,
        last_error = null;
end;
$$;


ALTER FUNCTION public.enqueue_email_signature_notification_lifecycle_for_company(p_actor_user_id uuid, p_connection_id uuid, p_company_id uuid, p_reason text) OWNER TO postgres;

--
-- Name: has_permission(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.has_permission(p_user_id uuid, p_permission text, p_required_scope text DEFAULT 'all'::text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_scope text;
begin
  if p_user_id is null or p_permission is null then
    return false;
  end if;

  select actor.company_id
  into v_company_id
  from public.users actor
  join public.companies company
    on company.id = actor.company_id
   and company.deleted_at is null
  where actor.id = p_user_id
    and actor.deleted_at is null
    and coalesce(actor.is_active, false);

  if not found then
    return false;
  end if;

  if private.user_is_company_admin(p_user_id, v_company_id) then
    return true;
  end if;

  v_scope := private.raw_permission_scope_for_user(
    p_user_id,
    v_company_id,
    p_permission
  );

  if v_scope = 'all' then
    return true;
  end if;
  if v_scope = 'assigned' then
    return p_required_scope in ('assigned', 'own');
  end if;
  if v_scope = 'own' then
    return p_required_scope = 'own';
  end if;
  return false;
end;
$$;


ALTER FUNCTION public.has_permission(p_user_id uuid, p_permission text, p_required_scope text) OWNER TO postgres;

