-- Name: email_assignment_contact_form_draft_queue; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.email_assignment_contact_form_draft_queue (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    assignment_event_id uuid NOT NULL,
    company_id uuid NOT NULL,
    opportunity_id uuid NOT NULL,
    assignment_version bigint NOT NULL,
    actor_user_id uuid NOT NULL,
    connection_id uuid NOT NULL,
    source_activity_id uuid NOT NULL,
    provider_message_id text NOT NULL,
    source_provider_thread_id text NOT NULL,
    customer_email text NOT NULL,
    customer_name text,
    source_subject text NOT NULL,
    source_body_text text NOT NULL,
    draft_history_id uuid,
    reused_from_draft_history_id uuid,
    mailbox_draft_id text,
    outreach_provider_thread_id text,
    provider_create_attempt_id uuid,
    provider_create_started_at timestamp with time zone,
    status text DEFAULT 'pending'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    available_at timestamp with time zone DEFAULT now() NOT NULL,
    lease_holder text,
    lease_expires_at timestamp with time zone,
    prepared_at timestamp with time zone,
    completed_at timestamp with time zone,
    result_reason text,
    last_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    mailbox_busy_since timestamp with time zone,
    CONSTRAINT email_assignment_contact_form_d_source_provider_thread_id_check CHECK ((btrim(source_provider_thread_id) <> ''::text)),
    CONSTRAINT email_assignment_contact_form_draft_completion_shape CHECK ((((status = 'completed'::text) AND (completed_at IS NOT NULL) AND (draft_history_id IS NOT NULL) AND (NULLIF(btrim(mailbox_draft_id), ''::text) IS NOT NULL) AND (NULLIF(btrim(outreach_provider_thread_id), ''::text) IS NOT NULL) AND (provider_create_attempt_id IS NOT NULL) AND (provider_create_started_at IS NOT NULL) AND (result_reason = 'drafted'::text)) OR ((status = 'skipped'::text) AND (completed_at IS NOT NULL) AND (mailbox_draft_id IS NULL) AND (outreach_provider_thread_id IS NULL) AND (result_reason = ANY (ARRAY['autonomy_ineligible'::text, 'draft_unavailable'::text, 'lead_terminal'::text, 'already_replied'::text, 'not_contact_form'::text]))) OR ((status = 'reconciliation_required'::text) AND (completed_at IS NOT NULL) AND (provider_create_attempt_id IS NOT NULL) AND (provider_create_started_at IS NOT NULL) AND (result_reason = 'provider_reconciliation_required'::text)) OR ((status <> ALL (ARRAY['completed'::text, 'skipped'::text, 'reconciliation_required'::text])) AND (completed_at IS NULL) AND (result_reason IS NULL)))),
    CONSTRAINT email_assignment_contact_form_draft_lease_shape CHECK ((((status = 'processing'::text) AND (lease_holder IS NOT NULL) AND (lease_expires_at IS NOT NULL)) OR ((status <> 'processing'::text) AND (lease_holder IS NULL) AND (lease_expires_at IS NULL)))),
    CONSTRAINT email_assignment_contact_form_draft_q_provider_message_id_check CHECK ((btrim(provider_message_id) <> ''::text)),
    CONSTRAINT email_assignment_contact_form_draft_qu_assignment_version_check CHECK ((assignment_version > 0)),
    CONSTRAINT email_assignment_contact_form_draft_queu_source_body_text_check CHECK ((btrim(source_body_text) <> ''::text)),
    CONSTRAINT email_assignment_contact_form_draft_queue_attempts_check CHECK ((attempts >= 0)),
    CONSTRAINT email_assignment_contact_form_draft_queue_customer_email_check CHECK ((btrim(customer_email) <> ''::text)),
    CONSTRAINT email_assignment_contact_form_draft_queue_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'retrying'::text, 'completed'::text, 'skipped'::text, 'failed'::text, 'stale'::text, 'reconciliation_required'::text])))
);


