CREATE TABLE public.users (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    bubble_id text,
    company_id uuid,
    first_name text NOT NULL,
    last_name text NOT NULL,
    email text,
    phone text,
    home_address text,
    profile_image_url text,
    user_color text,
    role text DEFAULT 'unassigned'::text,
    user_type text,
    is_company_admin boolean DEFAULT false,
    has_completed_tutorial boolean DEFAULT false,
    dev_permission boolean DEFAULT false,
    latitude double precision,
    longitude double precision,
    location_name text,
    client_id text,
    is_active boolean DEFAULT true,
    stripe_customer_id text,
    device_token text,
    auth_id text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    deleted_at timestamp with time zone,
    firebase_uid text,
    special_permissions text[] DEFAULT '{}'::text[],
    email_domain_valid boolean,
    removed_from_email_list boolean DEFAULT false,
    removed_from_email_list_at timestamp with time zone,
    fab_actions text[],
    setup_progress jsonb DEFAULT '{}'::jsonb,
    emergency_contact_name text,
    emergency_contact_phone text,
    emergency_contact_relationship text,
    onboarding_completed jsonb DEFAULT '{}'::jsonb,
    onesignal_player_id text,
    preferences jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT users_role_check CHECK ((role = ANY (ARRAY['admin'::text, 'owner'::text, 'office'::text, 'operator'::text, 'crew'::text, 'unassigned'::text]))),
    CONSTRAINT users_user_type_check CHECK ((user_type = ANY (ARRAY['employee'::text, 'company'::text, 'client'::text, 'admin'::text])))
);

ALTER TABLE ONLY public.users REPLICA IDENTITY FULL;


ALTER TABLE public.users OWNER TO postgres;

