--

CREATE INDEX activities_agent_sales_truth_history_v1_idx ON public.activities USING btree (company_id, opportunity_id, created_at, id) WHERE ((opportunity_id IS NOT NULL) AND (type = ANY (ARRAY['email'::text, 'text_message'::text])) AND (direction = ANY (ARRAY['inbound'::text, 'outbound'::text])));


