--

CREATE UNIQUE INDEX activities_email_provider_identity_unique ON public.activities USING btree (company_id, email_connection_id, email_message_id) WHERE ((email_connection_id IS NOT NULL) AND (email_message_id IS NOT NULL) AND (btrim(email_message_id) <> ''::text));


