CREATE INDEX clients_agent_active_normalized_email_idx ON public.clients USING btree (company_id, lower(btrim(email)), id) WHERE ((deleted_at IS NULL) AND (merged_into_client_id IS NULL));


--
-- Name: clients_agent_discovery_exact_email_idx; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX clients_agent_discovery_exact_email_idx ON public.clients USING btree (company_id, private.agent_normalize_discovery_email(email), "left"(private.agent_normalize_discovery_text(name), 200) COLLATE "C", id) WHERE ((deleted_at IS NULL) AND (merged_into_client_id IS NULL));


--
-- Name: clients_agent_discovery_exact_phone_idx; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX clients_agent_discovery_exact_phone_idx ON public.clients USING btree (company_id, private.agent_normalize_discovery_phone(phone_number), "left"(private.agent_normalize_discovery_text(name), 200) COLLATE "C", id) WHERE ((deleted_at IS NULL) AND (merged_into_client_id IS NULL));


--
-- Name: clients_agent_discovery_invalid_source_idx; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX clients_agent_discovery_invalid_source_idx ON public.clients USING btree (company_id, id) WHERE ((deleted_at IS NULL) AND (merged_into_client_id IS NULL) AND ((NULLIF(private.agent_trim_discovery_display_text(name), ''::text) IS NULL) OR (octet_length(private.agent_trim_discovery_display_text(name)) > 1000) OR (private.agent_normalize_discovery_text(name) IS NULL)));


--
-- Name: clients_agent_discovery_name_prefix_idx; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX clients_agent_discovery_name_prefix_idx ON public.clients USING btree (company_id, "left"(private.agent_normalize_discovery_text(name), 200) COLLATE "C", id) WHERE ((deleted_at IS NULL) AND (merged_into_client_id IS NULL));


--
-- Name: clients_agent_discovery_name_trgm_idx; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX clients_agent_discovery_name_trgm_idx ON public.clients USING gin (private.agent_normalize_discovery_text(name) COLLATE "C" public.gin_trgm_ops) WHERE ((deleted_at IS NULL) AND (merged_into_client_id IS NULL));


